window.__BUNDLE = {"body": "<div class=\"wrap\">\n\n  <section id=\"intro\" class=\"stack\" style=\"gap:28px\">\n    <div data-greeting></div>\n    <div id=\"testStart\" class=\"stack\" style=\"gap:28px\" hidden>\n    <div class=\"stack\">\n      <div class=\"eyebrow\">Selbsttest für Paare · drei Rollen · 15 Minuten</div>\n      <h1>Die Rose der Liebe</h1>\n      <p class=\"lead\">Ein Mann lebt in der Beziehung drei Rollen: Liebhaber, Ehemann, Vater. Eine Frau: Liebhaberin, Ehefrau, Mutter. Jede Rolle nährt einen Bestandteil der Liebe. Harmonie entsteht, wenn alle drei lebendig sind.</p>\n    </div>\n    <div class=\"roles\">\n      <div class=\"role r0\"><b>Liebhaber · Liebhaberin</b><span>Anziehung, Leidenschaft</span></div>\n      <div class=\"role r1\"><b>Ehemann · Ehefrau</b><span>Nähe, Vertrauen</span></div>\n      <div class=\"role r2\"><b>Vater · Mutter</b><span>Verantwortung, Halt</span></div>\n    </div>\n    <div class=\"card stack\">\n      <h3>So funktioniert es</h3>\n      <p>Hier gibt es keine Fragen zu Gefühlen, nur zu Taten. Der Partner sieht unsere Absichten nicht, er sieht, was wir tun. Denk an die letzten 4 Wochen und kreuze an, wie oft das wirklich so war.</p>\n      <p>Zwei Teile mit je 30 Aussagen. <b>Teil 1:</b> was du tust. <b>Teil 2:</b> wie dein Partner oder deine Partnerin sich dir gegenüber zeigt. Am Ende bekommst du eine ausführliche Auswertung: das Porträt der Frau, das Porträt des Mannes, das Dreieck eurer Beziehung, Empfehlungen und Fragen zum Nachdenken. Die Auswertung kannst du als PDF erhalten.</p>\n      <div class=\"scale-legend\"><span><b>0</b> nie</span><span><b>1</b> 1–2 Mal</span><span><b>2</b> ab und zu</span><span><b>3</b> oft</span><span><b>4</b> fast immer</span></div>\n      <p class=\"note\">Wenn ihr keine Kinder habt, bezieh die Aussagen über Kinder auf euer Zuhause, eure Nächsten und eure gemeinsame Zukunft.</p>\n    </div>\n    <div data-testinfo></div>\n    <div class=\"stack\">\n      <h3>Wie heisst ihr?</h3>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"nameMe\">Dein Name</label><input id=\"nameMe\" maxlength=\"30\" autocomplete=\"given-name\" placeholder=\"Zum Beispiel Anna\"></div>\n        <div class=\"field\"><label for=\"nameP\">Name des Partners</label><input id=\"nameP\" maxlength=\"30\" placeholder=\"Zum Beispiel Michael\"></div>\n      </div>\n      <p class=\"note\">Die Namen werden nur für eine schöne Auswertung gebraucht.</p>\n    </div>\n    <div class=\"stack\">\n      <h3>Wer macht den Test?</h3>\n      <div class=\"choices\">\n        <button class=\"choice\" id=\"pick-f\" data-g=\"f\"><b>Ich bin eine Frau</b><span>Liebhaberin, Ehefrau, Mutter</span></button>\n        <button class=\"choice\" id=\"pick-m\" data-g=\"m\"><b>Ich bin ein Mann</b><span>Liebhaber, Ehemann, Vater</span></button>\n      </div>\n    </div>\n    <div data-share=\"compact\" style=\"margin-top:8px\"></div>\n    </div>\n  </section>\n\n  <section id=\"quiz\" class=\"stack\" hidden style=\"gap:20px\">\n    <div class=\"stack\" style=\"gap:10px\">\n      <div class=\"row\" style=\"justify-content:space-between\">\n        <span class=\"eyebrow\" id=\"stepLabel\">Schritt 1 von 6</span>\n        <span class=\"eyebrow\" id=\"countLabel\">0 von 60</span>\n      </div>\n      <div class=\"progress\"><i id=\"prog\" style=\"width:0\"></i></div>\n    </div>\n    <div class=\"stack\" style=\"gap:6px\">\n      <div><span class=\"part-tag\" id=\"partTag\"></span></div>\n      <h2 id=\"roleTitle\"></h2>\n      <p class=\"muted\" id=\"roleSub\"></p>\n    </div>\n    <div class=\"card\" id=\"qlist\" style=\"padding-block:6px\"></div>\n    <div class=\"row\" style=\"justify-content:space-between\">\n      <button class=\"btn ghost\" id=\"back\">Zurück</button>\n      <button class=\"btn\" id=\"next\" disabled>Weiter</button>\n    </div>\n  </section>\n\n  <section id=\"result\" hidden>\n    <div class=\"rep\" id=\"report\"></div>\n    <div data-share style=\"margin-top:18px\"></div>\n    <div data-lead></div>\n  </section>\n\n  <div data-disclaimer style=\"margin-top:28px\"></div>\n</div>\n<div class=\"pdf-stage\" id=\"stage\" aria-hidden=\"true\"></div>\n", "scripts": ["/* Настройки сайта, общие для всех тестов */\n// Ссылка веб-приложения Google Apps Script (заканчивается на /exec). Одна на все тесты.\nconst ENDPOINT = 'https://script.google.com/macros/s/AKfycbyizp1XjzNdrUj4WHgj4Vyj81QhjY2D7puqyeY3LaweWB4mePxPhfHCx5fIsfaJy9hV/exec';\n// Адрес сайта после размещения, например 'https://irina-tests.netlify.app/' (нужен для ссылок в PDF)\nconst SITE_URL = 'https://irynawiederkehr-cmd.github.io/tests/';\n// Ссылки на тесты, пока сайт не размещён (используются для кнопки «Поделиться» и блока «Пройди также»).\n// После размещения сайта достаточно заполнить SITE_URL — эти ссылки больше не понадобятся.\nconst TEST_LINKS = {\n  'roza-lyubvi': 'https://claude.ai/artifact/6Nv7pCtqpAd9xoWUkvEwS1',\n  'kompas': 'https://claude.ai/artifact/5TPCgkiVSZEr8H2g8d1UkY'\n};\n", "const BRAND = 'psy';\nconst TEST_META = { id: 'roza-lyubvi', name: 'Die Rose der Liebe' };\nconst TEST_INFO = {\n  why: 'Ich habe diesen Fragebogen entwickelt, damit Paare ihre Beziehung nicht durch Kränkungen und Erwartungen sehen, sondern durch konkrete Taten. Oft lieben beide, aber jede und jeder liest Liebe in der eigenen Sprache. Der Fragebogen übersetzt Gefühle in die Sprache der Taten und zeigt, wo es in eurer Beziehung klingt und wo es still geworden ist.',\n  gives: [\n    'Du siehst, welche der drei Rollen du deutlich lebst und welche noch leise klingen.',\n    'Du vergleichst, was du in die Beziehung gibst und was du von deinem Partner oder deiner Partnerin bekommst.',\n    'Du erfährst, welcher Typ Paar ihr seid, nach der Dreieckstheorie der Liebe von Robert Sternberg.',\n    'Du bekommst einen Plan mit kleinen Schritten für 4 Wochen und Fragen für ein Gespräch zu zweit.'\n  ],\n  next: [\n    'Zieh keine voreiligen Schlüsse: Das Ergebnis ist eine Momentaufnahme der letzten 4 Wochen, kein Urteil über eure Beziehung.',\n    'Wähle eine Handlung aus dem Plan und setze sie mindestens eine Woche lang um.',\n    'Schlag deinem Partner oder deiner Partnerin vor, den Test auch zu machen, und vergleicht eure Dreiecke in Ruhe, ohne Vorwürfe.',\n    'Mach den Test in 4 Wochen noch einmal und schau, was sich verändert hat.',\n    'Wenn das Gespräch nicht gelingt oder das Thema schmerzt, besprich das Ergebnis mit einer Fachperson.'\n  ]\n};\n", "/* язык страницы: задаёт загрузчик (ru, uk, de, en) */\nconst DATE_LOCALE = ({ ru:'ru-RU', uk:'uk-UA', de:'de-CH', en:'en-GB' })[(typeof LANG !== 'undefined') ? LANG : 'ru'] || 'ru-RU';\n/* =====================================================================\n   Общие тексты и блоки для всех тестов Ирины Вознесенской.\n   Меняешь здесь — меняется во всех тестах сразу.\n   ===================================================================== */\n\n/* ---------- Обо мне и контакты ---------- */\nconst AUTHOR = {\n  name: 'Iryna Voznesenskaya',\n  about: 'ICF-Coach in der Schweiz und Psychologin in der Ukraine.',\n  coach: { place: 'Schweiz · Zürich', title: 'Coach', text: 'Transformations-Coach und Neurocoach, ICF. Ich begleite russischsprachige Emigrantinnen und Emigranten durch die Anpassung: sich selbst und den eigenen Platz in der neuen Welt zu finden. In der Schweiz arbeite ich ausschliesslich als Coach. Coaching ist keine Psychotherapie und ersetzt keine psychologische oder medizinische Behandlung.',\n           instagram: 'https://www.instagram.com/iryna.voznesenskaya/', telegram: 'https://t.me/IrynaNeuroCoach_channel' },\n  psy:   { place: 'Ukraine · Kyjiw', title: 'Psychologin in der Ukraine', text: 'Ich arbeite mit Paarbeziehungen: Ich helfe Paaren, einander zu hören, Nähe zurückzugewinnen und ein Gleichgewicht zu finden. Als Psychologin arbeite ich nur mit Klientinnen und Klienten in der Ukraine, auf Grundlage meiner ukrainischen Qualifikation.',\n           instagram: 'https://www.instagram.com/voznesenskayairyna.psy/', telegram: 'https://t.me/IrynaVoznesenska_psy' }\n};\n\n/* ---------- Все тесты (для главной и блока «Пройди также») ---------- */\nconst TESTS = [\n  { id: 'roza-lyubvi', path: 'roza-lyubvi/', name: 'Die Rose der Liebe', brand: 'psy', tag: 'Für Paare · 15 Minuten',\n    text: 'Drei Rollen in der Beziehung: Anziehung, Nähe und Verantwortung. Finde heraus, welche Rollen deutlich klingen, welche leiser geworden sind und wie ihr einander begegnet.' },\n  { id: 'kompas', path: 'kompas/', name: 'Kompass der Anpassung', brand: 'coach', tag: 'Für dich · 10 Minuten',\n    text: 'Wo du gerade in der Emigration stehst: sechs Bereiche deines neuen Lebens, dein Weg zwischen zwei Kulturen und der nächste kleine Schritt.' }\n];\n\nconst handle = url => '@' + url.replace(/\\/+$/, '').split('/').pop();\nconst pickOne = arr => arr[Math.floor(Math.random() * arr.length)];\nconst BASE = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n\nfunction practiceHtml(key){\n  const p = AUTHOR[key];\n  const links = [\n    p.instagram ? `<a href=\"${p.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram ${handle(p.instagram)}</a>` : '',\n    p.telegram ? `<a href=\"${p.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram-Kanal</a>` : ''\n  ].filter(Boolean).join('');\n  return `<div class=\"practice ${key}\"><span class=\"place\">${p.place}</span><h4>${p.title}</h4><p>${p.text}</p><div class=\"links\">${links}</div></div>`;\n}\nfunction authorHtml(label = 'Über die Autorin des Tests'){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  return `<div class=\"blk author\"><div class=\"eyebrow\">${label}</div>\n    <div class=\"who\"><div class=\"mono\">IV</div><div><b>${AUTHOR.name}</b><span>${AUTHOR.about}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div></div>`;\n}\nfunction footerLine(){\n  return BRAND === 'coach' ? 'Iryna Voznesenskaya · ICF-Coach (Schweiz) · Psychologin (Ukraine)' : 'Iryna Voznesenskaya · Psychologin (Ukraine) · ICF-Coach (Schweiz)';\n}\n\n/* ---------- Приветствие и обязательный мини-опрос ---------- */\nconst SURVEY = {\n  heard: { q: 'Woher kennst du mich?', opts: ['Instagram','Telegram','Empfehlung von Freunden oder Bekannten','Google-Suche','Facebook','Anderes'] },\n  interest: { q: 'Was interessiert dich?', opts: ['Psychologie: Beziehung als Paar','Coaching: Anpassung in der Emigration und zu sich selbst finden','Einfach so, aus Neugier'] }\n};\nconst GREET = {\n  head: ['Hallo! Ich bin {A}','Schön, dass du da bist! Ich heisse {A}','Willkommen! Ich bin {A}','Grüss dich! Ich bin {A}'],\n  about: ['ICF-Coach in der Schweiz und Psychologin in der Ukraine.','Ich arbeite in zwei Ländern: als ICF-Coach in der Schweiz und als Psychologin in der Ukraine.','Ich helfe Menschen, zu sich selbst zu finden und warme Beziehungen aufzubauen: als ICF-Coach in der Schweiz und als Psychologin in der Ukraine.'],\n  ask: ['Beantworte bitte vor dem Test zwei kurze Fragen. So verstehe ich besser, wie ich dir nützlich sein kann.',\n        'Zwei kurze Fragen vor dem Start, und dann geht es direkt zum Test.',\n        'Mir ist wichtig zu wissen, wer meine Tests macht. Beantworte bitte zwei kurze Fragen.']\n};\nfunction greetingHtml(){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  const group = key => `<fieldset class=\"survey\"><legend>${SURVEY[key].q} *</legend>${SURVEY[key].opts.map((o, i) =>\n    `<label class=\"check\"><input type=\"checkbox\" id=\"sv-${key}-${i}\" data-sv=\"${key}\" value=\"${o}\"> <span>${o}</span></label>`).join('')}</fieldset>`;\n  return `<div class=\"blk author greet\">\n    <div class=\"who\"><div class=\"mono\">IV</div><div><b>${pickOne(GREET.head).replace('{A}', AUTHOR.name)}</b><span>${pickOne(GREET.about)}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div>\n    <div class=\"stack\" style=\"gap:10px\"><p class=\"note\">${pickOne(GREET.ask)} Du kannst mehrere Antworten ankreuzen.</p>\n      <div class=\"surveys\">${group('heard')}${group('interest')}</div>\n      <p class=\"err\" id=\"svErr\" hidden></p>\n      <div><button class=\"btn\" type=\"button\" id=\"svGo\">Weiter zum Test</button></div></div></div>`;\n}\nfunction surveyAnswers(){\n  const pick = key => [...document.querySelectorAll(`input[data-sv=\"${key}\"]:checked`)].map(i => i.value);\n  return { heard: pick('heard'), interest: pick('interest') };\n}\n\n/* ---------- Живое приглашение в работу (тексты каждый раз собираются заново) ---------- */\nconst INVITES = {\n  psy: {\n    open: ['{N}, danke für deine ehrlichen Antworten.',\n           '{N}, du machst schon einen wichtigen Schritt: Du schaust ehrlich auf eure Beziehung.',\n           '{N}, diese Auswertung ist erst der Anfang eines Gesprächs.',\n           '{N}, der Test zeigt ein Bild, echte Veränderung beginnt im Gespräch.',\n           '{N}, hinter jeder Zahl in dieser Auswertung steht deine Geschichte.'],\n    body: ['Die Zahlen zeigen, wo es in eurer Beziehung still geworden ist. Doch dahinter steht immer etwas Eigenes: Müdigkeit, Kränkungen, Gewohnheiten, unausgesprochene Erwartungen. Im Gespräch schauen wir behutsam auf deine Situation und finden erste Schritte, damit {F}.',\n           'Manchmal genügt eine einzige treffende Frage, damit ein Paar einander wieder hört. Wenn du dir wünschst, dass {F}, lade ich dich zu einem Gespräch ein: ruhig, behutsam, ohne Bewertung.',\n           'Beziehungen verändern sich nicht durch Wissen, sondern durch neue Handlungen. Ich helfe Paaren, diese Handlungen zu finden und sie nicht nach einer Woche wieder aufzugeben. Lass uns gemeinsam schauen, was es braucht, damit {F}.',\n           'Den Weg zur Veränderung kann man allein gehen oder mit Unterstützung. Im Gespräch schauen wir dein Dreieck an und überlegen, was es braucht, damit {F}.',\n           'Viele Paare leben jahrelang mit derselben Spannung, weil sie nicht wissen, wie sie das Gespräch beginnen sollen. Ich helfe dir, es so zu beginnen, dass {F}.'],\n    cta:  ['Melde dich für ein Kennenlerngespräch von 30 Minuten an: Wir besprechen dein Ergebnis und entscheiden, ob eine weitere Arbeit an der Beziehung sinnvoll ist.',\n           '30 Minuten online. Du erzählst, ich höre zu und stelle Fragen. Nach dem Gespräch wird klarer, was in eurer Beziehung passiert und wo du anfangen kannst.',\n           'Das erste Gespräch dauert 30 Minuten. Das reicht, um dein Anliegen zu verstehen und einen Weg für die Arbeit an der Beziehung zu skizzieren.'],\n    title: ['Ich lade dich zu einem Gespräch von 30 Minuten ein','Lass uns über eure Beziehung sprechen','Der nächste Schritt: ein Gespräch'],\n    legal: 'Psychologische Beratungen finden online für Klientinnen und Klienten in der Ukraine statt.'\n  },\n  coach: {\n    open: ['{N}, danke, dass du dir Zeit für dich nimmst.',\n           '{N}, du machst schon einen wichtigen Schritt: Du schaust ehrlich und behutsam auf dich.',\n           '{N}, diese Auswertung ist erst der Anfang des Weges.',\n           '{N}, manchmal öffnet ein Test mehr Fragen als Antworten. Und das ist gut so.',\n           '{N}, alles, was du jetzt siehst, kann zu einer Stütze werden.'],\n    body: ['Die Emigration verändert alles: Sprache, Gewohnheiten, Rollen in der Familie und sogar, wie wir uns selbst sehen. Im Coaching suchen wir deine Stützen in der neuen Welt und helfen dir Schritt für Schritt, {F}.',\n           'Wenn sich das Land ändert, verändern auch wir uns. Manchmal fühlt sich das an, als würde man sich selbst verlieren. Ich helfe dir, dich neu zu finden, um {F}.',\n           'Du hast schon einen grossen Weg hinter dir. Coaching hilft dir, diese Erfahrung in Kraft zu verwandeln und {F}.',\n           'Die Antworten sind schon in dir, aber im Trubel des neuen Lebens sind sie schwer zu hören. In der Arbeit mit mir findest du deine Antworten und entscheidest, was dir hilft, {F}.',\n           'Anpassung bedeutet nicht nur Papiere und Sprache. Es ist die Suche nach dem eigenen Platz. Lass uns gemeinsam schauen, was dir hilft, {F}.'],\n    cta:  ['Melde dich für ein Kennenlerngespräch von 30 Minuten an: Wir sprechen über dein Anliegen und darüber, wie die Arbeit an dir selbst aussehen kann.',\n           '30 Minuten online. Du erzählst, was dir gerade wichtig ist, ich stelle Fragen. Nach dem Gespräch wird klarer, wohin du gehen willst.',\n           'Das erste Gespräch dauert 30 Minuten. Das reicht, um dein Anliegen zu verstehen und erste Schritte zu skizzieren.'],\n    title: ['Ich lade dich zu einem Gespräch von 30 Minuten ein','Lass uns über dich sprechen','Der nächste Schritt: ein Gespräch'],\n    legal: 'Coaching ist keine Psychotherapie und ersetzt keine psychologische oder medizinische Behandlung.'\n  }\n};\nconst INVITE_FOCUS_DEFAULT = { psy: 'in eurer Beziehung mehr Wärme und Verständnis entsteht', coach: 'deinen Platz in der neuen Welt zu finden' };\nlet inviteSeed = null;\nfunction resetInvite(){ inviteSeed = null; }\nfunction invitePractice(country){\n  // как психолог Ирина работает только с клиентами в Украине; остальных приглашаем в коучинг\n  if (BRAND === 'psy' && country && country !== 'Украина') return 'coach';\n  return BRAND;\n}\nfunction inviteHtml(ctx){\n  if (!inviteSeed) inviteSeed = Array.from({length:6}, () => Math.random());\n  const key = invitePractice(ctx.country);\n  const P = INVITES[key], A = AUTHOR[key];\n  const pick = (arr, i) => arr[Math.floor(inviteSeed[i] * arr.length)];\n  const N = ctx.name || '';\n  const F = (ctx.focus && ctx.focus[key]) || INVITE_FOCUS_DEFAULT[key];\n  const fill = t => { let s = N ? t.replace('{N}', N) : t.replace('{N}, ', ''); s = s.replace('{F}', F); return s.charAt(0).toUpperCase() + s.slice(1); };\n  const links = [A.telegram ? `<a href=\"${A.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram: ${A.telegram.replace('https://','')}</a>` : '',\n                 A.instagram ? `<a href=\"${A.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram: ${handle(A.instagram)}</a>` : ''].filter(Boolean);\n  const other = key === 'psy' ? 'coach' : 'psy';\n  const wantsOther = (ctx.interest || []).some(x => other === 'coach' ? /^Coaching/.test(x) : /^Psychologie/.test(x));\n  const otherLine = wantsOther && !(other === 'psy' && ctx.country && ctx.country !== 'Украина')\n    ? `<p class=\"note\">Dich interessiert auch die Richtung «${AUTHOR[other].title}». Mehr über diese Arbeit erfährst du hier: <a href=\"${AUTHOR[other].telegram}\" target=\"_blank\" rel=\"noopener\">${AUTHOR[other].telegram.replace('https://','')}</a></p>` : '';\n  return `<div class=\"blk invite ${key}\">\n    <div class=\"eyebrow\">${key === 'psy' ? 'Arbeit an der Beziehung' : 'Arbeit an dir selbst'}</div>\n    <h2>${pick(P.title, 0)}</h2>\n    <p class=\"lead\"><b>${fill(pick(P.open, 1))}</b></p>\n    <p>${fill(pick(P.body, 2))}</p>\n    <div class=\"invite-cta\"><p>${fill(pick(P.cta, 3))}</p>\n      <p><b>So meldest du dich an:</b> Schreib mir das Wort <b>«TERMIN»</b>, und ich schlage dir eine passende Zeit vor.</p>\n      <div class=\"invite-links\">${links.join('')}</div></div>\n    ${otherLine}\n    <p class=\"note\">${P.legal}</p></div>`;\n}\n\n/* ---------- Пройди также ---------- */\nfunction testUrl(t){\n  if (typeof SITE_URL !== 'undefined' && SITE_URL) return SITE_URL.replace(/\\/?$/, '/') + t.path;\n  if (typeof TEST_LINKS !== 'undefined' && TEST_LINKS[t.id]) return TEST_LINKS[t.id];\n  return BASE + t.path;\n}\nfunction moreTestsHtml(currentId){\n  const list = TESTS.filter(t => t.id !== currentId);\n  if (!list.length) return '';\n  return `<div class=\"blk more\"><div class=\"eyebrow\">Mach auch diesen Test</div>\n    <div class=\"tcards\">${list.map(t => `<a class=\"tcard ${t.brand}\" href=\"${testUrl(t)}\" target=\"_blank\" rel=\"noopener\">\n      <span class=\"ttag\">${t.tag}</span><b>${t.name}</b><span>${t.text}</span><span class=\"tgo\">Zum Test →</span></a>`).join('')}</div></div>`;\n}\n\n/* ---------- Об этом опроснике + дисклеймер ---------- */\nconst DISCLAIMER = [\n  'Dieser Fragebogen ist ein Werkzeug zur Selbsterkenntnis und für Gespräche. Er ist keine psychologische oder medizinische Diagnostik und kein psychotherapeutischer Befund und ersetzt keine Beratung durch eine Fachperson.',\n  'Die Ergebnisse spiegeln deine persönliche Wahrnehmung der letzten 4 Wochen wider und können sich verändern.',\n  'Wenn du eine Krise, Gewalt oder eine Bedrohung deiner Sicherheit erlebst, wende dich an eine Fachperson oder an die Notdienste deines Landes.'\n];\nfunction testInfoHtml(){\n  if (typeof TEST_INFO === 'undefined') return '';\n  return `<div class=\"blk testinfo\"><div class=\"eyebrow\">Über diesen Fragebogen</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>\n    <div class=\"ti-cols\">\n      <div><h3>Was dir der Test gibt</h3><ul class=\"clean\">${TEST_INFO.gives.map(x => `<li>${x}</li>`).join('')}</ul></div>\n      <div><h3>Was du damit tun kannst</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div>\n    </div></div>`;\n}\nfunction disclaimerHtml(){\n  return `<div class=\"disclaimer\"><b>Wichtig</b>${DISCLAIMER.map(x => `<p>${x}</p>`).join('')}</div>`;\n}\n\n/* ---------- Поделиться тестом ---------- */\nconst SHARE_TEXT = {\n  'roza-lyubvi': ['Ich habe den Paartest «Die Rose der Liebe» gemacht. Spannend und sehr treffend. Mach ihn auch, dann vergleichen wir:',\n                  'Ich habe den Test «Die Rose der Liebe» entdeckt: 15 Minuten, und man sieht, welche Rollen in der Beziehung deutlich klingen und welche leiser geworden sind. Probier es aus:'],\n  'kompas':      ['Ich habe den Test «Kompass der Anpassung» gemacht, für alle, die in der Emigration leben. Er hilft sehr zu verstehen, wo man gerade steht. Probier es aus:',\n                  'Ich habe den Test «Kompass der Anpassung» entdeckt: 10 Minuten, und man sieht, was im neuen Land schon zur Stütze geworden ist und wo es noch still ist. Probier es aus:']\n};\nconst SHARE_ICON = {\n  share: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3v12M7 8l5-5 5 5M5 13v6a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  wa: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 20l1.2-4A8 8 0 1 1 8 18.8z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M9 9.5c0 3 2.5 5.5 5.5 5.5l1-1.5-2-1-1 1c-1-.5-1.5-1-2-2l1-1-1-2z\" fill=\"currentColor\"/></svg>',\n  tg: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 4 3 11l6 2 2 6 3-4 5 4z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"m9 13 8-6\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>',\n  copy: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"8\" y=\"8\" width=\"12\" height=\"12\" rx=\"2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>'\n};\nfunction shareData(){\n  const t = TESTS.find(x => typeof TEST_META !== 'undefined' && x.id === TEST_META.id) || TESTS[0];\n  return { url: testUrl(t), text: pickOne(SHARE_TEXT[t.id] || ['Probier diesen Test aus:']), title: t.name };\n}\nfunction shareHtml(compact){\n  if (typeof TEST_META === 'undefined') return '';\n  const head = compact\n    ? `<p class=\"note\">Kennst du jemanden, dem dieser Test auch helfen könnte? Leite den Link weiter.</p>`\n    : `<div class=\"eyebrow\">Teilen</div><h3>Schick den Test deinen Freundinnen und Freunden</h3><p>Wenn dir der Test geholfen hat, schick ihn Menschen, denen er auch helfen kann. ${TEST_META.id === 'roza-lyubvi' ? 'Noch besser: Schlag deinem Partner oder deiner Partnerin vor, ihn auch zu machen, und vergleicht eure Ergebnisse.' : 'Vor allem denen, die auch vor kurzem umgezogen sind.'}</p>`;\n  return `<div class=\"${compact ? 'share compact' : 'blk share'}\">${head}\n    <div class=\"share-btns\">\n      ${navigator.share ? `<button type=\"button\" class=\"main\" data-share-act=\"native\">${SHARE_ICON.share}Teilen</button>` : ''}\n      <button type=\"button\" data-share-act=\"wa\">${SHARE_ICON.wa}WhatsApp</button>\n      <button type=\"button\" data-share-act=\"tg\">${SHARE_ICON.tg}Telegram</button>\n      <button type=\"button\" data-share-act=\"copy\">${SHARE_ICON.copy}Link kopieren</button>\n    </div>\n    <div class=\"share-link\" hidden><input readonly aria-label=\"Link zum Test\"></div>\n    <span class=\"share-ok\" hidden></span></div>`;\n}\nfunction openExternal(url){\n  const w = window.open(url, '_blank', 'noopener');\n  if (!w) location.href = url;\n}\ndocument.addEventListener('click', async (ev) => {\n  const b = ev.target.closest('[data-share-act]'); if (!b) return;\n  const box = b.closest('.share'), d = shareData(), act = b.dataset.shareAct;\n  const ok = box.querySelector('.share-ok');\n  const showOk = t => { ok.textContent = t; ok.hidden = false; setTimeout(() => ok.hidden = true, 4000); };\n  if (act === 'native'){\n    try { await navigator.share({ title: d.title, text: d.text, url: d.url }); return; }\n    catch(e){ if (e && e.name === 'AbortError') return; }\n  }\n  if (act === 'wa') return openExternal('https://wa.me/?text=' + encodeURIComponent(d.text + ' ' + d.url));\n  if (act === 'tg') return openExternal('https://t.me/share/url?url=' + encodeURIComponent(d.url) + '&text=' + encodeURIComponent(d.text));\n  try { await navigator.clipboard.writeText(d.text + ' ' + d.url); showOk('Link kopiert. Füge ihn in eine Nachricht an eine Freundin oder einen Freund ein.'); }\n  catch(e){\n    const row = box.querySelector('.share-link'), inp = row.querySelector('input');\n    inp.value = d.url; row.hidden = false; inp.focus(); inp.select();\n    showOk('Kopiere den Link aus dem Feld oben.');\n  }\n});\n\n/* ---------- Отрисовка общих блоков на странице ---------- */\ndocument.documentElement.dataset.brand = BRAND;\ndocument.querySelectorAll('[data-author]').forEach(el => el.innerHTML = authorHtml());\ndocument.querySelectorAll('[data-greeting]').forEach(el => el.innerHTML = greetingHtml());\ndocument.querySelectorAll('[data-testinfo]').forEach(el => el.innerHTML = testInfoHtml());\ndocument.querySelectorAll('[data-disclaimer]').forEach(el => el.innerHTML = disclaimerHtml());\ndocument.querySelectorAll('[data-share]').forEach(el => el.innerHTML = shareHtml(el.dataset.share === 'compact'));\n(function(){\n  const go = document.getElementById('svGo'); if (!go) return;\n  go.addEventListener('click', () => {\n    const a = surveyAnswers(), err = document.getElementById('svErr');\n    const miss = !a.heard.length ? 'Kreuze bitte an, woher du mich kennst.' : !a.interest.length ? 'Kreuze bitte an, was dich interessiert.' : '';\n    err.textContent = miss; err.hidden = !miss;\n    if (miss) return;\n    document.querySelector('[data-greeting]').hidden = true;\n    document.getElementById('testStart').hidden = false;\n    window.scrollTo(0, 0);\n  });\n})();\n", "/* ---------- акварельная роза для «Розы любви» ----------\n   Три круга лепестков: внутри притяжение, в середине близость, снаружи ответственность.\n   Чем сильнее составляющая у пары, тем крупнее её лепестки. */\nconst ROSE = { f: ['#EEA9B3','#B0DCC0','#A6C4F0'], l: ['#C25468','#4E9A70','#3F6FBF'], leafF: '#C9E6D2', leafL: '#4E9A70' };\nlet roseN = 0;\nfunction roseSVG(sc){\n  const id = 'rose' + (++roseN), cx = 150, cy = 130;\n  const k = i => 0.55 + 0.45 * Math.max(sc[i], 2) / 40;           // масштаб круга\n  const petal = (w, h) => `M0 0 C ${w} ${-h * .2}, ${w * .9} ${-h * .9}, 0 ${-h} C ${-w * .9} ${-h * .9}, ${-w} ${-h * .2}, 0 0Z`;\n  const ring = (i, n, w, h, rot0) => {\n    const s = k(i); let out = '';\n    for (let j = 0; j < n; j++){\n      const rot = rot0 + j * 360 / n;\n      out += `<g transform=\"translate(${cx} ${cy}) rotate(${rot}) scale(${s.toFixed(3)})\"><g filter=\"url(#${id}w)\"><path d=\"${petal(w, h)}\" fill=\"${ROSE.f[i]}\" opacity=\".88\"/><path d=\"${petal(w * .6, h * .7)}\" fill=\"${ROSE.f[i]}\" opacity=\".7\"/></g>\n        <path d=\"${petal(w, h)}\" fill=\"none\" stroke=\"${ROSE.l[i]}\" stroke-width=\"${(1.6 / s).toFixed(2)}\"/></g>`;\n    }\n    return out;\n  };\n  return `<svg viewBox=\"0 0 300 300\" role=\"img\" aria-label=\"Die Rose der Liebe eurer Beziehung\"><defs>\n      <filter id=\"${id}w\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\"><feTurbulence type=\"fractalNoise\" baseFrequency=\"0.04\" numOctaves=\"3\" seed=\"${roseN * 5}\" result=\"n\"/><feDisplacementMap in=\"SourceGraphic\" in2=\"n\" scale=\"7\" result=\"d\"/><feGaussianBlur in=\"d\" stdDeviation=\"0.7\"/></filter>\n      <filter id=\"${id}b\"><feGaussianBlur stdDeviation=\"14\"/></filter></defs>\n    <circle cx=\"80\" cy=\"80\" r=\"55\" fill=\"${ROSE.f[0]}\" opacity=\".3\" filter=\"url(#${id}b)\"/>\n    <circle cx=\"225\" cy=\"200\" r=\"60\" fill=\"${ROSE.f[2]}\" opacity=\".3\" filter=\"url(#${id}b)\"/>\n    <path d=\"M150 190 C146 220 152 250 148 292\" fill=\"none\" stroke=\"${ROSE.leafL}\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n    <g filter=\"url(#${id}w)\"><path d=\"M149 240 C120 222 98 230 88 246 C112 258 134 254 149 240Z\" fill=\"${ROSE.leafF}\"/><path d=\"M150 214 C178 196 202 202 212 218 C190 232 166 228 150 214Z\" fill=\"${ROSE.leafF}\"/></g>\n    <path d=\"M149 240 C120 222 98 230 88 246 C112 258 134 254 149 240Z M150 214 C178 196 202 202 212 218 C190 232 166 228 150 214Z\" fill=\"none\" stroke=\"${ROSE.leafL}\" stroke-width=\"1.6\"/>\n    ${ring(2, 7, 46, 104, 0)}\n    ${ring(1, 6, 36, 78, 25)}\n    ${ring(0, 5, 26, 52, 10)}\n    <circle cx=\"${cx}\" cy=\"${cy}\" r=\"9\" fill=\"${ROSE.f[0]}\" stroke=\"${ROSE.l[0]}\" stroke-width=\"1.6\"/>\n  </svg>`;\n}\nfunction roseLegend(sc){\n  const n = ['Anziehung','Nähe','Verantwortung'];\n  return `<div class=\"rose-legend\">${n.map((x, i) => `<span><i style=\"background:${ROSE.f[i]};border-color:${ROSE.l[i]}\"></i>${x} · ${sc[i]}</span>`).join('')}</div>`;\n}\n", "/* Items: own actions (first person) and the same actions as seen in the partner (third person). */\nconst SELF = {\n  f: [\n    ['Ich ergreife selbst die Initiative für Intimität.',\n     'Ich mache ihm Komplimente als Mann: über sein Aussehen, seine Stärke, darüber, was mich an ihm anzieht.',\n     'Ich mache mich für die Zeit mit ihm zurecht, um ihm zu gefallen, und nicht nur «zum Ausgehen» oder für die Arbeit.',\n     'Ich flirte mit ihm: ein Blick, ein Scherz, eine Andeutung, eine Berührung «einfach so».',\n     'Ich umarme und küsse ihn nicht im Vorbeigehen, sondern nehme mir Zeit dafür.',\n     'Ich schaffe Zeit nur für uns zwei: ein Date, einen Abend ohne Kinder, Gäste und Handys.',\n     'Ich probiere mit ihm etwas Neues aus: einen Ort, eine Aktivität, ein Erlebnis.',\n     'Ich sage oder schreibe ihm, dass ich ihn begehre und ihn vermisse.',\n     'Ich sorge für mich (Erholung, Körper, Stimmung), um erfüllt zu ihm zu kommen und nicht ausgelaugt.',\n     'Ich lege meine Aufgaben beiseite, wenn er mich zu Zeit zu zweit einlädt.'],\n    ['Ich frage, wie sein Tag war, und höre bis zum Ende zu, ohne zu unterbrechen und ohne Ratschläge zu geben.',\n     'Ich erzähle ihm von meinen Gefühlen und Sorgen, nicht nur von Aufgaben und Neuigkeiten.',\n     'Ich danke ihm für konkrete Taten und sage, wofür genau.',\n     'Ich stehe vor anderen zu ihm: vor den Kindern, der Verwandtschaft, Freunden.',\n     'Ich bespreche mich mit ihm, bevor ich eine wichtige Entscheidung treffe.',\n     'Ich rede mit ihm mindestens 20 Minuten am Stück ohne Handy.',\n     'Ich interessiere mich für seine Arbeit, seine Hobbys, seine Pläne und stelle Fragen.',\n     'Im Streit spreche ich über meine Gefühle und Bedürfnisse, statt ihm Vorwürfe zu machen oder ihn zu kritisieren.',\n     'Nach einem Streit mache ich einen Schritt zur Versöhnung, ohne zu warten, bis er den ersten macht.',\n     'Ich lache mit ihm, erinnere mich an Schönes, träume von unserer Zukunft.'],\n    ['Ich halte, was ich verspreche, pünktlich und ohne Erinnerung.',\n     'Ich kümmere mich so um die Kinder und die Familienangelegenheiten, dass er sich auf mich verlassen kann.',\n     'Ich schaffe zu Hause Gemütlichkeit und Ordnung, in der wir uns beide wohlfühlen.',\n     'Ich kümmere mich um seine Gesundheit und sein Wohlbefinden, ohne Kontrolle und Vorwürfe.',\n     'Ich plane das Budget und grössere Ausgaben mit.',\n     'Ich pflege Familientraditionen und Rituale: gemeinsame Abendessen, Feste, Wochenenden.',\n     'Ich pflege die Beziehung zu seiner und meiner Familie so, dass sie unsere Familie stärkt.',\n     'Ich lasse ihn auf seine Art Vater sein: Ich übernehme nicht für ihn, korrigiere ihn nicht und kritisiere ihn nicht vor den Kindern.',\n     'In schwierigen Situationen bleibe ich an seiner Seite und übernehme meinen Teil.',\n     'Ich spreche mit ihm über unsere Zukunft: Ziele, Pläne, Entscheidungen für die kommenden Jahre.']\n  ],\n  m: [\n    ['Ich ergreife behutsam die Initiative für Intimität und achte auf ihre Stimmung.',\n     'Ich mache ihr Komplimente als Frau: über ihre Schönheit, darüber, was mich an ihr anzieht.',\n     'Ich mache ihr den Hof: Blumen, kleine Überraschungen, Aufmerksamkeiten ohne Anlass.',\n     'Ich lade sie zu einem Date ein und organisiere alles selbst.',\n     'Ich berühre sie zärtlich auch ausserhalb des Bettes: Ich umarme sie, nehme ihre Hand, streichle ihr über den Rücken.',\n     'Ich achte auf mein Aussehen und meine Form, auch ihr zuliebe.',\n     'Ich probiere mit ihr etwas Neues aus: einen Ort, eine Aktivität, ein Erlebnis.',\n     'Ich sage oder schreibe ihr, dass ich sie begehre und sie vermisse.',\n     'Ich sage laut, wie sie aussieht: ein neues Kleid, eine neue Frisur, ihre Stimmung.',\n     'Ich schaffe eine Atmosphäre für uns zwei: einen Abend ohne Kinder, Gäste und Handys, den ich vorbereitet habe.'],\n    ['Ich höre ihr bis zum Ende zu, ohne zu unterbrechen und ohne gleich zu Lösungen überzugehen.',\n     'Ich erzähle ihr von meinen Gefühlen, Zweifeln und Sorgen, nicht nur von Fakten.',\n     'Ich danke ihr für konkrete Dinge, auch für die unsichtbare Arbeit in Haushalt und Familie.',\n     'Ich stelle mich vor anderen auf ihre Seite: vor den Kindern, der Verwandtschaft, Freunden.',\n     'Ich bespreche mich mit ihr, bevor ich eine wichtige Entscheidung treffe.',\n     'Ich rede mit ihr mindestens 20 Minuten am Stück ohne Handy.',\n     'Ich interessiere mich für ihre Arbeit, ihre Freundinnen, Hobbys und Pläne und stelle Fragen.',\n     'Im Streit spreche ich ruhig über meine Gefühle, ohne Vorwürfe und ohne mich ins Schweigen zurückzuziehen.',\n     'Nach einem Streit mache ich einen Schritt zur Versöhnung, ohne zu warten, bis sie den ersten macht.',\n     'Ich lache mit ihr, erinnere mich an Schönes, träume von unserer Zukunft.'],\n    ['Ich halte, was ich verspreche, pünktlich und ohne Erinnerung.',\n     'Ich sehe selbst, was zu Hause zu tun ist, und erledige es, ohne dass sie mich bitten muss.',\n     'Ich verbringe persönlich Zeit mit den Kindern: Spielen, Gespräche, Hausaufgaben, Spaziergänge.',\n     'Ich sorge für finanzielle Stabilität und spreche offen mit ihr über Geld.',\n     'Ich bringe Alltagsaufgaben zu Ende: Reparaturen, Dokumente, Termine, Defekte.',\n     'Ich kümmere mich um die Sicherheit und Gesundheit der Familie, auch um meine eigene.',\n     'Ich pflege Familientraditionen und Rituale: gemeinsame Abendessen, Feste, Wochenenden.',\n     'Ich übernehme Kinder und Haushalt, damit sie Zeit für sich hat.',\n     'In schwierigen Situationen bleibe ich an ihrer Seite und ziehe mich nicht in die Arbeit, die Garage oder das Handy zurück.',\n     'Ich spreche mit ihr über unsere Zukunft: Ziele, Pläne, Entscheidungen für die kommenden Jahre.']\n  ]\n};\nconst OTHER = {\n  m: [ // the man, as seen by the woman\n    ['Er ergreift behutsam die Initiative für Intimität und achtet auf meine Stimmung.',\n     'Er macht mir Komplimente als Frau: über meine Schönheit, darüber, was ihn an mir anzieht.',\n     'Er macht mir den Hof: Blumen, kleine Überraschungen, Aufmerksamkeiten ohne Anlass.',\n     'Er lädt mich zu einem Date ein und organisiert alles selbst.',\n     'Er berührt mich zärtlich auch ausserhalb des Bettes: Er umarmt mich, nimmt meine Hand, streichelt mir über den Rücken.',\n     'Er achtet auf sein Aussehen und seine Form, auch mir zuliebe.',\n     'Er probiert mit mir etwas Neues aus: einen Ort, eine Aktivität, ein Erlebnis.',\n     'Er sagt oder schreibt mir, dass er mich begehrt und mich vermisst.',\n     'Er sagt laut, wie ich aussehe: ein neues Kleid, eine neue Frisur, meine Stimmung.',\n     'Er schafft eine Atmosphäre für uns zwei: einen Abend ohne Kinder, Gäste und Handys, den er vorbereitet hat.'],\n    ['Er hört mir bis zum Ende zu, ohne zu unterbrechen und ohne gleich zu Lösungen überzugehen.',\n     'Er erzählt mir von seinen Gefühlen, Zweifeln und Sorgen, nicht nur von Fakten.',\n     'Er dankt mir für konkrete Dinge, auch für die unsichtbare Arbeit in Haushalt und Familie.',\n     'Er stellt sich vor anderen auf meine Seite: vor den Kindern, der Verwandtschaft, Freunden.',\n     'Er bespricht sich mit mir, bevor er eine wichtige Entscheidung trifft.',\n     'Er redet mit mir mindestens 20 Minuten am Stück ohne Handy.',\n     'Er interessiert sich für meine Arbeit, meine Freundinnen, Hobbys und Pläne und stellt Fragen.',\n     'Im Streit spricht er ruhig über seine Gefühle, ohne Vorwürfe und ohne sich ins Schweigen zurückzuziehen.',\n     'Nach einem Streit macht er einen Schritt zur Versöhnung, ohne zu warten, bis ich den ersten mache.',\n     'Er lacht mit mir, erinnert sich an Schönes, träumt von unserer Zukunft.'],\n    ['Er hält, was er verspricht, pünktlich und ohne Erinnerung.',\n     'Er sieht selbst, was zu Hause zu tun ist, und erledigt es, ohne dass ich ihn bitten muss.',\n     'Er verbringt persönlich Zeit mit den Kindern: Spielen, Gespräche, Hausaufgaben, Spaziergänge.',\n     'Er sorgt für finanzielle Stabilität und spricht offen mit mir über Geld.',\n     'Er bringt Alltagsaufgaben zu Ende: Reparaturen, Dokumente, Termine, Defekte.',\n     'Er kümmert sich um die Sicherheit und Gesundheit der Familie, auch um seine eigene.',\n     'Er pflegt Familientraditionen und Rituale: gemeinsame Abendessen, Feste, Wochenenden.',\n     'Er übernimmt Kinder und Haushalt, damit ich Zeit für mich habe.',\n     'In schwierigen Situationen bleibt er an meiner Seite und zieht sich nicht in die Arbeit, die Garage oder das Handy zurück.',\n     'Er spricht mit mir über unsere Zukunft: Ziele, Pläne, Entscheidungen für die kommenden Jahre.']\n  ],\n  f: [ // the woman, as seen by the man\n    ['Sie ergreift selbst die Initiative für Intimität.',\n     'Sie macht mir Komplimente als Mann: über mein Aussehen, meine Stärke, darüber, was sie an mir anzieht.',\n     'Sie macht sich für die Zeit mit mir zurecht, um mir zu gefallen, und nicht nur «zum Ausgehen» oder für die Arbeit.',\n     'Sie flirtet mit mir: ein Blick, ein Scherz, eine Andeutung, eine Berührung «einfach so».',\n     'Sie umarmt und küsst mich nicht im Vorbeigehen, sondern nimmt sich Zeit dafür.',\n     'Sie schafft Zeit nur für uns zwei: ein Date, einen Abend ohne Kinder, Gäste und Handys.',\n     'Sie probiert mit mir etwas Neues aus: einen Ort, eine Aktivität, ein Erlebnis.',\n     'Sie sagt oder schreibt mir, dass sie mich begehrt und mich vermisst.',\n     'Sie sorgt für sich (Erholung, Körper, Stimmung) und kommt erfüllt zu mir, nicht ausgelaugt.',\n     'Sie legt ihre Aufgaben beiseite, wenn ich sie zu Zeit zu zweit einlade.'],\n    ['Sie fragt, wie mein Tag war, und hört bis zum Ende zu, ohne zu unterbrechen und ohne Ratschläge zu geben.',\n     'Sie erzählt mir von ihren Gefühlen und Sorgen, nicht nur von Aufgaben und Neuigkeiten.',\n     'Sie dankt mir für konkrete Taten und sagt, wofür genau.',\n     'Sie steht vor anderen zu mir: vor den Kindern, der Verwandtschaft, Freunden.',\n     'Sie bespricht sich mit mir, bevor sie eine wichtige Entscheidung trifft.',\n     'Sie redet mit mir mindestens 20 Minuten am Stück ohne Handy.',\n     'Sie interessiert sich für meine Arbeit, meine Hobbys, meine Pläne und stellt Fragen.',\n     'Im Streit spricht sie über ihre Gefühle und Bedürfnisse, statt mir Vorwürfe zu machen oder mich zu kritisieren.',\n     'Nach einem Streit macht sie einen Schritt zur Versöhnung, ohne zu warten, bis ich den ersten mache.',\n     'Sie lacht mit mir, erinnert sich an Schönes, träumt von unserer Zukunft.'],\n    ['Sie hält, was sie verspricht, pünktlich und ohne Erinnerung.',\n     'Sie kümmert sich so um die Kinder und die Familienangelegenheiten, dass ich mich auf sie verlassen kann.',\n     'Sie schafft zu Hause Gemütlichkeit und Ordnung, in der wir uns beide wohlfühlen.',\n     'Sie kümmert sich um meine Gesundheit und mein Wohlbefinden, ohne Kontrolle und Vorwürfe.',\n     'Sie plant das Budget und grössere Ausgaben mit.',\n     'Sie pflegt Familientraditionen und Rituale: gemeinsame Abendessen, Feste, Wochenenden.',\n     'Sie pflegt die Beziehung zu meiner und ihrer Familie so, dass sie unsere Familie stärkt.',\n     'Sie lässt mich auf meine Art Vater sein: Sie übernimmt nicht für mich, korrigiert mich nicht und kritisiert mich nicht vor den Kindern.',\n     'In schwierigen Situationen bleibt sie an meiner Seite und übernimmt ihren Teil.',\n     'Sie spricht mit mir über unsere Zukunft: Ziele, Pläne, Entscheidungen für die kommenden Jahre.']\n  ]\n};\nconst ROLES = { f: ['Liebhaberin','Ehefrau','Mutter'], m: ['Liebhaber','Ehemann','Vater'] };\nconst COMP = ['Anziehung','Nähe','Verantwortung'];\nconst VARS = ['--passion','--close','--resp'];\nconst SOFT = ['--passion-soft','--close-soft','--resp-soft'];\nconst LABELS = ['nie','1–2 Mal','manchmal','oft','fast immer'];\n\n/* ---------- content library ---------- */\nconst ROLE_INFO = {\n  f: ['Das ist die Frau, die begehrt wird. Diese Rolle steht für Lust, Spiel, Leichtigkeit und Interesse an ihrem Mann. Sie hält in der Beziehung den Funken lebendig und lässt die Beziehung nicht zu einem blossen Nebeneinander werden.',\n      'Das ist die Freundin und Verbündete. Diese Rolle steht für Vertrauen, Gespräche, Unterstützung und das Gefühl «wir sind ein Team». Sie gibt dem Mann das Gefühl, zu Hause verstanden zu werden.',\n      'Das ist der Halt der Familie. Diese Rolle steht für Verlässlichkeit, Fürsorge, das Zuhause und die gemeinsame Zukunft. Es geht nicht darum, dem Mann eine Mutter zu sein, sondern um reife Verantwortung für die gemeinsame Welt.'],\n  m: ['Das ist der Mann, der begehrt und wirbt. Diese Rolle steht für Werben, Initiative, Zärtlichkeit und Bewunderung für seine Frau. An seiner Seite fühlt sich die Frau begehrt.',\n      'Das ist der Freund und Partner. Diese Rolle steht dafür, zuhören zu können, Gefühle zu teilen und sich auf ihre Seite zu stellen. Sie gibt der Frau das Gefühl, nicht allein zu sein.',\n      'Das ist Halt und Schutz. Diese Rolle steht für ein gehaltenes Wort, für Zuhause, Kinder, Geld und Zukunft. An seiner Seite fühlt man sich ruhig und sicher.']\n};\nconst LV = [\n  ['Gerade klingt die Rolle «{R}» leise. Das kennen fast alle Paare: Lust, Spiel und Werben rücken unbemerkt in den Hintergrund, wenn viel Müdigkeit, Alltag, Kinder oder unausgesprochene Kränkungen da sind. Das bedeutet nicht, dass die Liebe fehlt, sondern dass diese Rolle lange keinen Platz bekommen hat. Die gute Nachricht: Sie spricht schon auf kleine Schritte an.',\n   'In der Rolle «{R}» zeigt sich {N} ab und zu. Der Funke ist da, aber er hängt von Stimmung und freier Zeit ab. Bei Stress und Müdigkeit erlischt diese Rolle als Erste, deshalb lohnt es sich, sie bewusst zu pflegen, statt auf Inspiration zu warten.',\n   '{N} zeigt sich deutlich in der Rolle «{R}». Lust, Interesse und Spiel leben in Taten, nicht nur in Gefühlen. Das hält ein Paar als Mann und Frau zusammen und nicht nur als Team.'],\n  ['Gerade klingt Nähe in Taten leise. Es gibt weniger offene Gespräche, Dankbarkeit und Unterstützung, und die Kommunikation dreht sich oft nur um Organisatorisches. In einem vollen Leben ist das sehr verständlich. Aber Nähe lässt sich leicht zurückholen: Manchmal genügen 20 Minuten Gespräch ohne Handy.',\n   '{N} zeigt Nähe, aber nicht beständig. Gute Gespräche gibt es, wenn Zeit und Stimmung da sind. In angespannten Zeiten schrumpft die Kommunikation auf Organisatorisches, und der andere kann sich unverstanden fühlen.',\n   '{N} zeigt sich lebendig in der Rolle «{R}»: hört zu, teilt, dankt, unterstützt. Mit so einem Menschen an der Seite spürst du, dass du nicht allein bist. Das ist das Fundament des Vertrauens in einer Beziehung.'],\n  ['Gerade klingt Verantwortung in Taten leise. Versprechen, das Zuhause, gemeinsame Pläne und die Zukunft bleiben noch im Schatten. Vielleicht fehlt einfach die Kraft dafür, oder die Rollen haben sich so verteilt. Es lohnt sich, behutsam miteinander zu besprechen, wer wofür Verantwortung tragen möchte.',\n   '{N} zeigt Verantwortung, aber nicht in allem. Bei manchen Dingen kann sich der andere auf sie oder ihn verlassen, bei anderen muss er oder sie erinnern oder alles selbst übernehmen. Es hilft, das ruhig zu vereinbaren, damit sich niemand mit den Sorgen allein fühlt.',\n   '{N} zeigt sich verlässlich in der Rolle «{R}»: hält Wort, kümmert sich um Zuhause und Zukunft, bleibt in schweren Momenten da. Das gibt dem Paar ein Gefühl von Sicherheit. Wichtig ist nur, dass die Verantwortung die anderen Rollen nicht verdrängt.']\n];\nconst LV_NAME = ['klingt noch leise','klingt ab und zu','klingt deutlich'];\nconst RECS = {\n  f: [['Plane einmal pro Woche einen Abend zu zweit: ohne Kinder, Gäste und Handys. Die Initiative liegt bei dir.',\n       'Sag ihm, was dich an ihm als Mann anzieht. Ganz konkret: seine Hände, seine Stimme, wie er etwas tut.',\n       'Nimm dir jeden Tag 15 Minuten für dich: Erholung, Körper, Stimmung. Es ist wichtig, erfüllt zu ihm zu kommen und nicht ausgelaugt.'],\n      ['Frag jeden Tag, wie sein Tag war, und hör bis zum Ende zu, ohne Ratschläge.',\n       'Danke für konkrete Taten: nicht einfach «danke», sondern «danke, dass du heute…».',\n       'Teile Gefühle, nicht nur Neuigkeiten: «Ich war heute aufgeregt, weil…».'],\n      ['Vereinbart zwei oder drei Familienrituale: ein gemeinsames Abendessen, ein Sonntagsspaziergang, ein Abend für Pläne.',\n       'Lass ihn auf seine Art Vater sein: Korrigiere ihn nicht und übernimm nicht für ihn vor den Kindern.',\n       'Sprecht einmal im Monat über die Zukunft: Ziele, Geld, Pläne für das Jahr.']],\n  m: [['Lade sie zu einem Date ein und organisiere alles selbst: Ort, Zeit, Betreuung der Kinder.',\n       'Sag ihr jeden Tag laut, wie sie aussieht und was dich an ihr anzieht.',\n       'Berühre sie zärtlich auch ausserhalb des Bettes: umarmen, ihre Hand nehmen, einfach so.'],\n      ['Hör ihr bis zum Ende zu, ohne gleich zu Lösungen überzugehen. Frag: «Brauchst du gerade einen Rat oder Unterstützung?»',\n       'Erzähl von deinen Gefühlen und Sorgen, nicht nur von Fakten und Aufgaben.',\n       'Danke ihr für die unsichtbare Arbeit: Haushalt, Kinder, Verwandtschaft, Alltag.'],\n      ['Sieh selbst, was zu Hause zu tun ist, und erledige es, ohne dass sie bitten muss.',\n       'Verbring persönlich Zeit mit den Kindern, ohne Handy, mindestens 30 Minuten am Tag.',\n       'Sprich offen mit ihr über Geld und Zukunft: Pläne, Entscheidungen, Ängste.']]\n};\nconst KEEP = 'Diese Rolle funktioniert schon. Behalte bei, was du tust, und achte darauf, dass sie die anderen nicht verdrängt.';\nconst PAIR = [\n  { strong:'Zwischen euch gibt es Lust und Spiel, und beide investieren darin. Das ist selten bei Paaren, die schon lange zusammen sind. Schützt eure Zeit zu zweit, auch wenn das Leben voll wird.',\n    weak:'Die Anziehung ist bei euch beiden leise geworden. Meist liegt es nicht an fehlenden Gefühlen, sondern an Müdigkeit, Alltag und Kindern. Die gute Nachricht: Anziehung lässt sich durch Taten wieder wecken. Beginnt klein: ein Date pro Woche und Berührungen ohne Anlass.',\n    mid:'Die Anziehung lebt, aber sie hängt vom Zufall ab. Damit der Funke nicht erlischt, braucht er einen Platz im Kalender: Geplante Zeit zu zweit wirkt besser, als auf die passende Stimmung zu warten.',\n    gap:'{A} investiert deutlich mehr in die Anziehung. Wer immer wieder einlädt, fühlt sich mit der Zeit gekränkt und einsam, und wer wenig darauf eingeht, kann Druck spüren. Wichtig ist, in Ruhe herauszufinden, was im Weg steht: Müdigkeit, Kränkung, Unsicherheit oder ein unterschiedliches Verständnis davon, was Begehren ist.' },\n  { strong:'Ihr seid Freunde und Verbündete: Ihr redet miteinander, unterstützt einander und dankt einander. Das ist der beste Schutz einer Beziehung vor Krisen.',\n    weak:'Die Nähe ist bei euch beiden leise geworden. Ihr seid zusammen, aber jede und jeder lebt mit den eigenen Sorgen für sich. Beginnt mit 20 Minuten Gespräch am Tag ohne Handys und der Frage «Wie geht es dir wirklich?».',\n    mid:'Nähe ist da, aber es fehlt ihr an Regelmässigkeit. Vereinbart ein kleines tägliches Gesprächsritual, damit sich eure Kommunikation nicht nur um Organisatorisches dreht.',\n    gap:'{A} investiert mehr in die Nähe: fragt nach, hört zu, teilt sich mit. Wer sich mehr öffnet, kann sich ungehört fühlen. Dem anderen fehlt oft einfach die Übung oder ein Vorbild. Hilfreich ist eine direkte Bitte: «Mir ist wichtig, dass du mich nach … fragst.»' },\n  { strong:'Ihr seid beide verlässlich: Ihr haltet Wort und kümmert euch um Zuhause und Zukunft. Das Paar fühlt sich sicher. Achtet darauf, dass die Verantwortung nicht die Zeit für Leidenschaft und Nähe auffrisst.',\n    weak:'Die Verantwortung kommt bei euch beiden zu kurz. Versprechen werden vergessen, Pläne verschoben, über die Zukunft wird nicht gesprochen. Beginnt mit einem Schritt: einmal im Monat ein Familienabend für Pläne.',\n    mid:'Die Verantwortung ist verteilt, aber ungleich und nicht immer ausgesprochen. Besprecht, wer wofür zuständig ist, damit niemand das Gefühl hat, mehr zu tragen.',\n    gap:'{A} trägt mehr Verantwortung für die gemeinsame Welt. Das führt direkt zu Müdigkeit und Gereiztheit beim einen und zu Passivität beim anderen. Setzt euch zusammen und verteilt die Bereiche neu: Haushalt, Geld, Kinder, Verwandtschaft, Pläne.' }\n];\nconst PAIR_TITLE = { strong:'Gemeinsame Stärke', weak:'Gemeinsames Wachstumsfeld', mid:'Da, aber vom Zufall abhängig', gap:'Ungleicher Beitrag' };\nconst QUEST = [\n  ['Wann hast du dich zuletzt begehrt gefühlt?','Was dämpft die Lust in eurer Beziehung: Müdigkeit, Kränkung, Alltag?','Wie war euer schönstes Date, und was habt ihr damals anders gemacht?'],\n  ['Worüber habt ihr lange nicht mehr wirklich gesprochen?','Fühlst du dich gehört? In welchen Momenten am meisten?','Was behältst du für dich und erzählst es deinem Partner oder deiner Partnerin nicht?'],\n  ['Worin kannst du dich auf dein Gegenüber verlassen und worin nicht?','Welche gemeinsame Entscheidung schiebt ihr schon lange auf?','Wie siehst du eure Beziehung in fünf Jahren?']\n];\nconst TYPES = {\n  '111':['Vollkommene Liebe','Ich begehre dich, ich kenne dich, ich wähle dich. In eurer Beziehung sind alle drei Bestandteile lebendig: Anziehung, Nähe und Verantwortung. Das ist die stabilste Form der Liebe, doch auch sie braucht Pflege. Das grösste Risiko: sich zu entspannen und aufzuhören, das zu tun, was schon funktioniert.'],\n  '110':['Romantische Liebe','Zwischen euch gibt es Leidenschaft und Nähe: Ihr seid gern zusammen, findet einander spannend und redet viel. Weniger sichtbar ist der Halt: gemeinsame Pläne, Verlässlichkeit, Zukunft. Solche Beziehungen sind lebendig und warm, aber in einer schweren Zeit kann das Fundament fehlen.'],\n  '011':['Freundschaftlicher Bund','Ihr seid verlässliche Partner und Freunde: Ihr unterstützt einander und gestaltet gemeinsam eure Welt. Die Anziehung ist in den Hintergrund gerückt. Viele Paare, die schon lange zusammen sind, landen unbemerkt hier. Das Risiko: wie «Bruder und Schwester» zu werden. Die gute Nachricht: Leidenschaft kehrt zurück, wenn man ihr wieder Zeit und Aufmerksamkeit schenkt.'],\n  '101':['Stürmische Liebe','Es gibt Leidenschaft und Verbindlichkeit, aber wenig echte Nähe und offene Gespräche. Ihr seid zusammen und fühlt euch zueinander hingezogen, wisst aber nicht immer, was im anderen vorgeht. Euer Weg führt über mehr Vertrauen und Offenheit.'],\n  '100':['Verliebtheit','Zwischen euch gibt es Anziehung, Nähe und Halt entstehen erst noch. Das ist lebendig und intensiv. Damit die Beziehung die Zeit übersteht, braucht es Freundschaft und eine gemeinsame Zukunft: miteinander reden, Vereinbarungen treffen, Wort halten.'],\n  '010':['Freundschaft und Zuneigung','Ihr fühlt euch miteinander warm und vertraut, ihr könnt reden und einander unterstützen. Anziehung und gemeinsame Zukunft zeigen sich in Taten aber kaum. Die Aufgabe: die Lust in die Beziehung zurückzuholen und gemeinsame Pläne Wirklichkeit werden zu lassen.'],\n  '001':['Von Sorgen erschöpfte Liebe','Ihr gestaltet eure gemeinsame Welt verlässlich, aber Leidenschaft und Nähe klingen gerade leise. Das ist ein sehr häufiger Zustand, wenn viele Kinder, viel Arbeit und viele Sorgen da sind. In Sternbergs Modell heisst er «leere Liebe», doch in Wirklichkeit ist die Liebe nicht verschwunden, sie ist nur müde. Mit kleinen Taten in den Rollen als Liebende und als Ehepartner lässt sie sich wieder beleben.'],\n  '000':['Das Dreieck braucht Aufmerksamkeit','Gerade zeigt sich keiner der Bestandteile deutlich. Das ist kein Urteil: So sieht ein Paar oft in einer schwierigen Phase aus, in Müdigkeit oder nach einer Krise. Von hier aus lässt sich gut beginnen. Schon kleine Taten werden sichtbar sein.']\n};\n\n/* ---------- state ---------- */\nlet g = null, step = 0, ans = [], names = {f:'', m:''};\nlet last = null;\nconst $ = id => document.getElementById(id);\nconst css = v => getComputedStyle(document.documentElement).getPropertyValue(v).trim();\nconst other = x => x === 'f' ? 'm' : 'f';\nconst sum = a => a.reduce((x,y) => x+y, 0);\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst lvl = s => s <= 15 ? 0 : s <= 27 ? 1 : 2;\nconst typeOf = sc => TYPES[sc.map(s => s >= 28 ? 1 : 0).join('')];\nconst fill = (t, o) => t.replace(/\\{(\\w)\\}/g, (_, k) => o[k]);\n\ndocument.querySelectorAll('.choice').forEach(b => b.addEventListener('click', () => {\n  g = b.dataset.g; resetInvite(); window.__leadCountry = '';\n  const me = $('nameMe').value.trim(), p = $('nameP').value.trim();\n  names[g] = me || (g === 'f' ? 'Frau' : 'Mann');\n  names[other(g)] = p || (g === 'f' ? 'Mann' : 'Frau');\n  step = 0; ans = Array.from({length:6}, () => Array(10).fill(null));\n  $('intro').hidden = true; $('quiz').hidden = false; renderStep(); window.scrollTo(0,0);\n}));\n\nfunction stepInfo(s){\n  const self = s < 3, k = s % 3;\n  const who = self ? g : other(g);\n  const items = self ? SELF[g][k] : OTHER[who][k];\n  const P = esc(names[other(g)]);\n  const pr = g === 'f' ? 'er' : 'sie';\n  const tag = self ? 'Teil 1 · Was ich tue' : `Teil 2 · Was ${P} tut`;\n  const title = self ? `Ich als ${ROLES[g][k]}` : `${P} als ${ROLES[who][k]}`;\n  const sub = self\n    ? ['Was du tust, damit zwischen euch Lust und Interesse lebendig bleiben.','Was du tust, damit ihr Freunde und ein Team bleibt.','Was du tust, damit man sich auf dich verlassen kann.'][k]\n    : [`Wie ${pr} zwischen euch Lust und Interesse lebendig hält.`,`Wie ${pr} dir Nähe und Freundschaft zeigt.`,`Wie sehr ${pr} dir Halt gibt.`][k];\n  return { k, items, tag, title, sub };\n}\nfunction renderStep(){\n  const info = stepInfo(step);\n  document.documentElement.style.setProperty('--accent', `var(${VARS[info.k]})`);\n  $('stepLabel').textContent = `Schritt ${step+1} von 6`;\n  $('partTag').innerHTML = info.tag;\n  $('roleTitle').innerHTML = `${info.title} <span class=\"muted\" style=\"font-size:.6em\">· ${COMP[info.k]}</span>`;\n  $('roleTitle').style.color = `var(${VARS[info.k]})`;\n  $('roleSub').textContent = info.sub + ' In den letzten 4 Wochen.';\n  const list = $('qlist'); list.innerHTML = '';\n  info.items.forEach((t, i) => {\n    const q = document.createElement('div'); q.className = 'q';\n    q.innerHTML = `<p><span class=\"n\">${step*10+i+1}.</span>${t}</p><div class=\"opts\" role=\"group\" aria-label=\"Bewertung\"></div>`;\n    const opts = q.querySelector('.opts');\n    for (let v = 0; v <= 4; v++){\n      const o = document.createElement('button'); o.className = 'opt'; o.id = `q${step}-${i}-${v}`;\n      o.setAttribute('aria-pressed', ans[step][i] === v ? 'true' : 'false');\n      o.innerHTML = `<b>${v}</b><small>${LABELS[v]}</small>`;\n      o.addEventListener('click', () => { ans[step][i] = v;\n        opts.querySelectorAll('.opt').forEach((x, n) => x.setAttribute('aria-pressed', n === v ? 'true' : 'false'));\n        update(); });\n      opts.appendChild(o);\n    }\n    list.appendChild(q);\n  });\n  $('next').textContent = step === 5 ? 'Auswertung anzeigen' : (step === 2 ? 'Weiter zu Teil 2' : 'Weiter');\n  update();\n}\nfunction update(){\n  const done = ans.flat().filter(v => v !== null).length;\n  $('countLabel').textContent = `${done} von 60`;\n  $('prog').style.width = (done/60*100) + '%';\n  $('next').disabled = ans[step].some(v => v === null);\n}\n$('next').addEventListener('click', () => { if (step < 5){ step++; renderStep(); window.scrollTo(0,0); } else showResult(); });\n$('back').addEventListener('click', () => {\n  if (step > 0){ step--; renderStep(); window.scrollTo(0,0); }\n  else { $('quiz').hidden = true; $('intro').hidden = false; }\n});\n\n/* ---------- pictures ---------- */\nfunction icon(k, color){\n  const p = [\n    `<path d=\"M12 2.5c.8 3.6 4.6 5.6 4.6 10.4a4.6 4.6 0 0 1-9.2 0c0-2.6 1.6-3.8 2-6.2 1 .9 1.7 2.2 1.8 3.6 1-1.9 1.2-4.8.8-7.8z\" fill=\"${color}\"/>`,\n    `<circle cx=\"9\" cy=\"12\" r=\"5.6\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2.4\"/><circle cx=\"15\" cy=\"12\" r=\"5.6\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2.4\"/>`,\n    `<path d=\"M3 11.2 12 3.5l9 7.7V21h-6.2v-5.6H9.2V21H3z\" fill=\"${color}\"/>`][k];\n  return `<svg viewBox=\"0 0 24 24\" width=\"24\" height=\"24\" aria-hidden=\"true\">${p}</svg>`;\n}\nfunction venn(){\n  const c = [css('--passion'), css('--close'), css('--resp')], ink = css('--ink');\n  return `<svg viewBox=\"0 0 300 260\" role=\"img\" aria-label=\"Drei Bestandteile der Liebe\">\n    <circle cx=\"150\" cy=\"92\" r=\"78\" fill=\"${c[0]}\" fill-opacity=\".55\"/>\n    <circle cx=\"104\" cy=\"170\" r=\"78\" fill=\"${c[1]}\" fill-opacity=\".55\"/>\n    <circle cx=\"196\" cy=\"170\" r=\"78\" fill=\"${c[2]}\" fill-opacity=\".55\"/>\n    <text x=\"150\" y=\"58\" text-anchor=\"middle\" font-family=\"Manrope, sans-serif\" font-weight=\"700\" font-size=\"13\" fill=\"${ink}\">Anziehung</text>\n    <text x=\"70\" y=\"200\" text-anchor=\"middle\" font-family=\"Manrope, sans-serif\" font-weight=\"700\" font-size=\"13\" fill=\"${ink}\">Nähe</text>\n    <text x=\"232\" y=\"200\" text-anchor=\"middle\" font-family=\"Manrope, sans-serif\" font-weight=\"700\" font-size=\"13\" fill=\"${ink}\">Verantwortung</text>\n    <text x=\"150\" y=\"150\" text-anchor=\"middle\" font-family=\"Forum, Georgia, serif\" font-size=\"18\" fill=\"${ink}\">Liebe</text>\n  </svg>`;\n}\nfunction triSVG(polys, labelVals){\n  const W = 420, H = 320, cx = 210, cy = 178, R = 116;\n  const ang = [-90, 30, 150].map(d => d*Math.PI/180);\n  const pt = (k, f) => [cx + R*f*Math.cos(ang[k]), cy + R*f*Math.sin(ang[k])];\n  const poly = f => [0,1,2].map(k => pt(k, f).map(n => n.toFixed(1)).join(',')).join(' ');\n  const line = css('--line'), muted = css('--muted');\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Dreieck\">`;\n  s += `<polygon points=\"${poly(1)}\" fill=\"${css('--paper')}\" />`;\n  [0.25,0.5,0.75,1].forEach(f => s += `<polygon points=\"${poly(f)}\" fill=\"none\" stroke=\"${line}\" stroke-width=\"${f===1?1.6:1}\"/>`);\n  [0,1,2].forEach(k => { const [x,y] = pt(k,1); s += `<line x1=\"${cx}\" y1=\"${cy}\" x2=\"${x}\" y2=\"${y}\" stroke=\"${line}\"/>`; });\n  polys.forEach(p => {\n    const pts = [0,1,2].map(k => pt(k, Math.max(p.sc[k],1)/40).map(n => n.toFixed(1)).join(',')).join(' ');\n    s += `<polygon points=\"${pts}\" fill=\"${p.color}\" fill-opacity=\"${p.fill ?? .22}\" stroke=\"${p.color}\" stroke-width=\"3\" stroke-linejoin=\"round\" ${p.dash ? 'stroke-dasharray=\"7 5\"' : ''}/>`;\n    [0,1,2].forEach(k => { const [x,y] = pt(k, Math.max(p.sc[k],1)/40); s += `<circle cx=\"${x}\" cy=\"${y}\" r=\"5\" fill=\"${p.color}\"/>`; });\n  });\n  const lab = [[cx, 30, 'middle'], [pt(1,1)[0]+10, pt(1,1)[1]+30, 'middle'], [pt(2,1)[0]-10, pt(2,1)[1]+30, 'middle']];\n  lab.forEach(([x,y,a], k) => {\n    s += `<text x=\"${x}\" y=\"${y}\" text-anchor=\"${a}\" font-family=\"Forum, Georgia, serif\" font-size=\"17\" fill=\"${css(VARS[k])}\">${labelVals[k][0]}</text>`;\n    s += `<text x=\"${x}\" y=\"${y+16}\" text-anchor=\"${a}\" font-family=\"Manrope, sans-serif\" font-size=\"11\" fill=\"${muted}\">${labelVals[k][1]}</text>`;\n  });\n  return s + '</svg>';\n}\nconst bar = (v, color) => `<div class=\"bar\"><i style=\"width:${v/40*100}%;background:${color}\"></i></div>`;\n\n/* ---------- report ---------- */\nfunction compute(){\n  const selfSc = ans.slice(0,3).map(sum), partSc = ans.slice(3).map(sum);\n  const isF = g === 'f';\n  const W = isF ? selfSc : partSc, M = isF ? partSc : selfSc;\n  const Wa = isF ? ans.slice(0,3) : ans.slice(3), Ma = isF ? ans.slice(3) : ans.slice(0,3);\n  const avg = [0,1,2].map(k => Math.round((W[k] + M[k]) / 2));\n  return { selfSc, partSc, W, M, Wa, Ma, avg, isF };\n}\n\nfunction buildBlocks(){\n  const r = compute(); last = r;\n  const { W, M, Wa, Ma, avg, isF, selfSc, partSc } = r;\n  const NF = esc(names.f), NM = esc(names.m), NS = esc(names[g]), NP = esc(names[other(g)]);\n  const her = css('--her'), him = css('--him'), plum = css('--plum');\n  const [pType, pText] = typeOf(avg);\n  const date = new Date().toLocaleDateString(DATE_LOCALE, {day:'numeric', month:'long', year:'numeric'});\n  const B = [];\n\n  // cover\n  B.push({ html: `<div class=\"blk hero\"><div class=\"split\">\n      <div class=\"stack\" style=\"gap:10px\"><div class=\"eyebrow\">Die Rose der Liebe · Auswertung</div>\n        <div class=\"names\">${NF} und ${NM}</div>\n        <h1>${pType}</h1>\n        <p class=\"note\">${date} · ausgefüllt von${isF ? '' : ''}: ${NS}</p></div>\n      <div class=\"fig\">${roseSVG(avg)}${roseLegend(avg)}</div></div></div>` });\n  B.push({ html: `<div class=\"blk\"><h3>Was das für eure Beziehung bedeutet</h3><p>${pText}</p>\n      <p class=\"note\">Der Typ eurer Beziehung ergibt sich aus den Durchschnittswerten beider Partner. Ein Bestandteil gilt ab 28 von 40 Punkten als stark.</p></div>` });\n  B.push({ html: `<div class=\"blk\"><h2>Das Dreieck eurer Beziehung</h2><div class=\"split\">\n      <div class=\"fig\" style=\"flex-basis:320px\">${triSVG([{sc:W,color:her,fill:.18},{sc:M,color:him,fill:.18},{sc:avg,color:plum,fill:0,dash:true}], [0,1,2].map(k => [COMP[k], `Paar: ${avg[k]} / 40`]))}</div>\n      <div class=\"stack\" style=\"gap:12px\">\n        <div class=\"legend\"><span><i style=\"background:${her}\"></i>${NF}</span><span><i style=\"background:${him}\"></i>${NM}</span><span><i style=\"border:2px dashed ${plum}\"></i>Paar im Durchschnitt</span></div>\n        ${[0,1,2].map(k => `<div class=\"stack\" style=\"gap:6px\"><div class=\"row\" style=\"gap:8px\">${icon(k, css(VARS[k]))}<b style=\"font-family:var(--display);font-weight:400;font-size:1.15rem;color:var(${VARS[k]})\">${COMP[k]}</b></div>\n          <div class=\"duo\"><span>${NF}</span>${bar(W[k], her)}<b style=\"color:${her}\">${W[k]}</b><span>${NM}</span>${bar(M[k], him)}<b style=\"color:${him}\">${M[k]}</b></div></div>`).join('')}\n      </div></div>\n      <p class=\"note\">Das Dreieck des Gegenübers beruht auf der Wahrnehmung der Person, die den Test gemacht hat (${NS}). ${NP} sieht sich vielleicht anders.</p></div>` });\n  B.push({ html: testInfoHtml() });\n\n  // portraits\n  const portrait = (gg, sc, color, softVar) => {\n    const N = esc(names[gg]); const [tn] = typeOf(sc);\n    const out = [{ newPage:true, html: `<div class=\"blk\" style=\"background:var(${softVar});border:none\"><div class=\"split\">\n        <div class=\"stack\" style=\"gap:8px\"><div class=\"eyebrow\">Porträt · ${gg === g ? 'Selbsteinschätzung' : 'aus Partnersicht'}</div>\n          <h2 style=\"color:${color}\">${N}</h2>\n          <p>${gg==='f' ? 'Liebhaberin, Ehefrau, Mutter' : 'Liebhaber, Ehemann, Vater'}. Insgesamt <b>${sum(sc)}</b> von 120. Form des Dreiecks: <b>${tn}</b>.</p>\n          ${sc.map((s,k) => `<div class=\"stack\" style=\"gap:4px\"><div class=\"row\" style=\"justify-content:space-between\"><span>${ROLES[gg][k]}</span><b style=\"color:var(${VARS[k]})\">${s} / 40</b></div>${bar(s, css(VARS[k]))}</div>`).join('')}\n        </div>\n        <div class=\"fig\">${triSVG([{sc, color}], [0,1,2].map(k => [`${ROLES[gg][k]} · ${sc[k]}`, LV_NAME[lvl(sc[k])]]))}</div></div></div>` }];\n    sc.forEach((s, k) => {\n      const l = lvl(s);\n      const recs = l === 2 ? `<p class=\"recs\" style=\"padding-left:14px;list-style:none\">${KEEP}</p>`\n        : `<div class=\"recs-t\">Was dir hilft</div><ul class=\"recs\">${RECS[gg][k].map(x => `<li>${x}</li>`).join('')}</ul>`;\n      out.push({ html: `<div class=\"blk role-blk\" style=\"--c:var(${VARS[k]});--cs:var(${SOFT[k]})\">\n        <div class=\"role-head\"><div class=\"ico\">${icon(k, css(VARS[k]))}</div><h3>${ROLES[gg][k]}</h3>\n          <span class=\"pill\" style=\"background:var(${VARS[k]})\">${LV_NAME[l]}</span><span class=\"sc\">${s} / 40</span></div>\n        <p class=\"note\" style=\"font-style:italic\">${ROLE_INFO[gg][k]}</p>\n        <p>${fill(LV[k][l], {N, R: ROLES[gg][k]})}</p>\n        ${recs}</div>` });\n    });\n    return out;\n  };\n  B.push(...portrait('f', W, her, '--her-soft'));\n  B.push(...portrait('m', M, him, '--him-soft'));\n\n  // interaction\n  B.push({ newPage:true, html: `<div class=\"blk plain\"><div class=\"eyebrow\">Analyse des Zusammenspiels</div><h2>Wie ihr einander begegnet</h2>\n    <p>Für jeden Bestandteil der Liebe werden die Taten beider Partner verglichen. Wichtig ist nicht nur, wie viel jede und jeder einbringt, sondern auch, wie gegenseitig dieser Beitrag ist.</p></div>` });\n  [0,1,2].forEach(k => {\n    const w = W[k], m = M[k], d = w - m;\n    let kind, A = '';\n    if (Math.abs(d) >= 8){ kind = 'gap'; A = d > 0 ? NF : NM; }\n    else if (w >= 28 && m >= 28) kind = 'strong';\n    else if (w <= 20 && m <= 20) kind = 'weak';\n    else kind = 'mid';\n    B.push({ html: `<div class=\"blk role-blk\" style=\"--c:var(${VARS[k]});--cs:var(${SOFT[k]})\">\n      <div class=\"role-head\"><div class=\"ico\">${icon(k, css(VARS[k]))}</div><h3>${COMP[k]}</h3>\n        <span class=\"pill\" style=\"background:var(${VARS[k]})\">${PAIR_TITLE[kind]}</span><span class=\"sc\">${avg[k]} / 40</span></div>\n      <div class=\"duo\"><span>${ROLES.f[k]} · ${NF}</span>${bar(w, her)}<b style=\"color:${her}\">${w}</b><span>${ROLES.m[k]} · ${NM}</span>${bar(m, him)}<b style=\"color:${him}\">${m}</b></div>\n      <p>${fill(PAIR[k][kind], {A})}</p></div>` });\n  });\n\n  // balance and traps\n  const notes = [];\n  const tW = sum(W), tM = sum(M), dT = tW - tM;\n  if (Math.abs(dT) <= 8) notes.push(['--resp','--resp-soft','Ausgewogenes Geben', `${NF} und ${NM} bringen sich etwa gleich viel in die Beziehung ein (${tW} und ${tM} von 120). Das ist eine gute Grundlage: Niemand fühlt sich als die einzige Person, die die Beziehung «trägt». Haltet dieses Gleichgewicht und sprecht aus, was der andere beiträgt.`]);\n  else {\n    const A = dT > 0 ? NF : NM, Bn = dT > 0 ? NM : NF;\n    notes.push(['--close','--close-soft','Der Beitrag ist noch ungleich verteilt', `${A} bringt sich deutlich mehr in die Beziehung ein (${Math.max(tW,tM)} zu ${Math.min(tW,tM)} von 120). Wer mehr gibt, kann mit der Zeit erschöpft sein, und der andere bemerkt es vielleicht nicht einmal. Es lohnt sich, zwei Dinge zu prüfen. Tut ${Bn} wirklich weniger, oder zeigt sich der Beitrag so, dass er schwer zu sehen ist? Und lässt ${A} dem Gegenüber Raum zum Handeln, oder übernimmt ${A} alles schon im Voraus?`]);\n  }\n  if ((W[2] >= 28 && W[0] <= 15) || (M[2] >= 28 && M[0] <= 15)) notes.push(['--passion','--passion-soft','Wenn die Eltern das Paar verdecken', 'Die Elternrolle nimmt gerade viel Raum ein, die Rolle als Liebhaber oder Liebhaberin klingt leiser. Im Alltag seid ihr ein tolles Team, und es lohnt sich, öfter einfach ein Paar zu sein. Das ist das häufigste Szenario nach der Geburt von Kindern. Der Ausweg: Zeit nur für euch zwei genauso ernsthaft zu schützen wie die Angelegenheiten der Kinder.']);\n  if (Ma[2][3] + Ma[2][4] >= 6 && Ma[2][2] + Ma[2][8] <= 3) notes.push(['--him','--him-soft','Wenn Versorgen die Anwesenheit ersetzt', `${NM} investiert viel in Geld und das Lösen von Aufgaben, aber weniger in echte Anwesenheit. Der Mann glaubt aufrichtig, dass er so seine Liebe zeigt. Doch Frau und Kinder spüren Liebe vor allem durch Zeit, Aufmerksamkeit und Gespräche.`]);\n  if (sum(Wa[2].slice(0,4)) >= 12 && (Wa[2][7] <= 1 || W[0] <= 15)) notes.push(['--her','--her-soft','Wenn Fürsorge zu Kontrolle wird', `Weibliche Fürsorge wird leicht zu Kontrolle: erinnern, überprüfen, korrigieren. Bei so viel Fürsorge fühlt sich der Mann nicht mehr als Mann, und die Frau wird müde von der Verantwortung für zwei. Vertrauen hilft: ihn etwas auf seine Art machen lassen, auch wenn es nicht perfekt ist.`]);\n  notes.forEach(([c, cs, t, x]) => B.push({ html: `<div class=\"callout\" style=\"--c:var(${c});--cs:var(${cs})\"><h3>${t}</h3><p>${x}</p></div>` }));\n\n  // plan\n  const weakest = selfSc.indexOf(Math.min(...selfSc));\n  const low = SELF[g][weakest].map((t,i) => [t, ans[weakest][i]]).sort((a,b) => a[1]-b[1]).slice(0,2);\n  const partStrong = partSc.indexOf(Math.max(...partSc));\n  const pairWeak = avg.indexOf(Math.min(...avg));\n  const ritual = ['Ein Date zu zweit einmal pro Woche: ohne Kinder, Gäste und Handys.','20 Minuten Gespräch jeden Abend: «Wie geht es dir wirklich?»','Ein Familienabend für Pläne einmal im Monat: Zuhause, Geld, Kinder, Träume.'][pairWeak];\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Plan für 4 Wochen</div><h2>Kleine Schritte, die eine Beziehung verändern</h2>\n    <div class=\"steps\">\n      <div><span class=\"num\">1</span><div><b>Dein Schritt: die Rolle «${ROLES[g][weakest]}»</b><p>Diese Rolle klingt gerade am leisesten. Wähle eine Handlung und setze sie mindestens zweimal pro Woche um:</p>\n        <ul class=\"clean\" style=\"margin-top:6px\">${low.map(([t]) => `<li>${t}</li>`).join('')}</ul></div></div>\n      <div><span class=\"num\">2</span><div><b>Dank an dein Gegenüber</b><p>Am stärksten zeigt sich dein Gegenüber in der Rolle «${ROLES[other(g)][partStrong]}». Sag das laut und nenne eine konkrete Tat. Ein Beitrag, der gesehen wird, wird gern fortgesetzt.</p></div></div>\n      <div><span class=\"num\">3</span><div><b>Gemeinsames Ritual für euch: ${COMP[pairWeak]}</b><p>${ritual}</p></div></div>\n      <div><span class=\"num\">4</span><div><b>In 4 Wochen</b><p>Mach den Test noch einmal, am besten zu zweit, und vergleicht eure Dreiecke.</p></div></div>\n    </div></div>` });\n\n  B.push({ html: `<div class=\"blk\"><h2>Fragen zum Nachdenken</h2><p class=\"note\">Beantworte sie für dich schriftlich, und wähle dann eine Frage aus, um sie mit deinem Gegenüber zu besprechen.</p>\n    <div class=\"qgrid\">${[0,1,2].map(k => `<div style=\"--c:var(${VARS[k]});--cs:var(${SOFT[k]})\"><div class=\"row\" style=\"gap:8px\">${icon(k, css(VARS[k]))}<h3>${COMP[k]}</h3></div><ul>${QUEST[k].map(q => `<li>${q}</li>`).join('')}</ul></div>`).join('')}</div></div>` });\n  B.push({ html: `<div class=\"blk\"><h3>Fragen für ein Gespräch zu zweit</h3><ul class=\"clean\">\n    <li>Wo ähneln sich unsere Dreiecke, und wo gehen sie auseinander? Was hat dich überrascht?</li>\n    <li>In welcher Rolle spürst du mich am stärksten? Und in welcher fehle ich dir?</li>\n    <li>Welche eine Handlung von mir würdest du schon diese Woche bemerken?</li>\n    <li>Wie war unsere Beziehung, als alle drei Rollen klangen? Was haben wir damals anders gemacht?</li></ul>\n    <p class=\"note\">Unterschiedliche Einschätzungen sind kein Grund zum Streiten, sondern eine Landkarte dafür, in welcher Sprache jede und jeder von euch Liebe liest.</p></div>` });\n\n  const nmSelf = ['Frau','Mann'].includes(names[g]) ? '' : names[g];\n  B.push({ html: inviteHtml({\n    name: nmSelf,\n    country: window.__leadCountry || '',\n    interest: (typeof surveyAnswers === 'function') ? surveyAnswers().interest : [],\n    focus: {\n      psy: ['Anziehung und Lust in eure Beziehung zurückkehren','Nähe und offene Gespräche zurückkehren','ihr einander ein verlässlicher Halt werdet'][pairWeak],\n      coach: ['dich selbst und deine Wünsche in Beziehungen besser zu verstehen','dir selbst mehr zu vertrauen und dich deinen Nächsten zu öffnen','ein Gleichgewicht zwischen der Fürsorge für andere und für dich selbst zu finden'][pairWeak]\n    }\n  }) });\n  B.push({ html: moreTestsHtml(TEST_META.id) });\n  B.push({ html: authorHtml() });\n  B.push({ html: disclaimerHtml() });\n\n  r.pType = pType; r.notes = notes.map(n => n[2]);\n  return B;\n}\n\nfunction showResult(){\n  const blocks = buildBlocks();\n  $('report').innerHTML = blocks.map(b => b.html).join('');\n  $('quiz').hidden = true; $('result').hidden = false; $('status').hidden = true; window.scrollTo(0,0);\n}\n\n\n/* ---------- связь с общей анкетой ---------- */\nconst LEAD_HOOKS = {\n  personName: () => (['Frau','Mann'].includes(names[g]) ? '' : names[g]),\n  fileBase: () => 'Roza_lyubvi',\n  fileNames: () => [names.f, names.m].filter(n => !['Frau','Mann'].includes(n)),\n  payload: () => {\n    const r = last, scores = {};\n    ROLES.f.forEach((x, k) => scores['Женщина: ' + x] = r.W[k]);\n    ROLES.m.forEach((x, k) => scores['Мужчина: ' + x] = r.M[k]);\n    COMP.forEach((x, k) => scores['Пара: ' + x] = r.avg[k]);\n    scores['Всего: женщина'] = sum(r.W); scores['Всего: мужчина'] = sum(r.M);\n    return { result: r.pType, scores, notes: `проходил${g === 'f' ? 'а женщина' : ' мужчина'}` + (r.notes.length ? '; ' + r.notes.join('; ') : '') };\n  }\n};\n\n/* значки на плитках ролей на стартовой странице */\ndocument.querySelectorAll('.roles .role').forEach((el, k) => {\n  const b = el.querySelector('b'); if (!b || k > 2) return;\n  const w = document.createElement('div'); w.className = 'ri';\n  w.innerHTML = icon(k, css(VARS[k])); b.parentNode.insertBefore(w, b); w.appendChild(b);\n});\n", "/* =====================================================================\n   Общая анкета перед PDF, отправка в Google Таблицу и сборка PDF.\n   Тест задаёт: TEST_META {id, name}, buildBlocks(), showResult(), LEAD_HOOKS.\n   ===================================================================== */\n/* Страны — коды ISO; названия показываются на языке страницы, в таблицу уходит русское название. */\nconst COUNTRY_TOP = ['CH','DE','AT','FR','IT','ES','NL','BE','GB','PL','CZ','IL','US','CA','UA','RU','BY','KZ'];\nconst COUNTRY_ALL = ['AU','AT','AZ','AL','DZ','AD','AR','AM','AF','BD','BH','BY','BE','BG','BO','BA','BR','GB','HU','VE','VN','GH','DE','HK','GR','GE','DK','DO','EG','IL','IN','ID','JO','IQ','IR','IE','IS','ES','IT','KZ','KH','CA','QA','KE','CY','KG','CN','CO','CR','CU','KW','LV','LB','LT','LI','LU','MU','MY','MV','MT','MA','MX','MD','MC','MN','ME','NP','NG','NL','NZ','NO','AE','OM','PK','PA','PY','PE','PL','PT','RU','RO','SA','MK','RS','SG','SK','SI','US','TJ','TH','TW','TN','TM','TR','UG','UZ','UA','UY','PH','FI','FR','HR','CZ','CL','CH','SE','LK','EC','EE','ZA','KR','JM','JP'];\nconst PAGE_LANG = (typeof LANG !== 'undefined') ? LANG : 'ru';\nconst countryName = (() => { try { const d = new Intl.DisplayNames([PAGE_LANG], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst countryRu = (() => { try { const d = new Intl.DisplayNames(['ru'], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst COUNTRIES = COUNTRY_ALL.map(countryRu);\nconst OTHER_COUNTRY = 'Другая страна';\n\nfunction leadFormHtml(){\n  return `<div class=\"blk actions\" style=\"margin-top:18px\">\n    <h3>Auswertung als PDF erhalten</h3>\n    <p>Ein schönes PDF mit deiner Auswertung, ohne die Testfragen: Bilder, Beschreibungen, Empfehlungen, ein Plan für 4 Wochen und Fragen zum Nachdenken. Hinterlasse deine Kontaktdaten, und die Datei wird sofort heruntergeladen.</p>\n    <form id=\"lead\" class=\"stack\" style=\"gap:12px\" novalidate>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fName\">Name *</label><input id=\"fName\" maxlength=\"40\" required autocomplete=\"given-name\"></div>\n        <div class=\"field\"><label for=\"fEmail\">E-mail *</label><input id=\"fEmail\" type=\"email\" maxlength=\"80\" required autocomplete=\"email\"></div>\n      </div>\n      <div class=\"field\"><label for=\"fContact\">Telegram oder WhatsApp</label><input id=\"fContact\" maxlength=\"60\" placeholder=\"@username oder +41 …\"></div>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fCountry\">Land *</label><select id=\"fCountry\" required><option value=\"\">Wähle ein Land</option></select></div>\n        <div class=\"field\"><label for=\"fCity\">Stadt</label><input id=\"fCity\" maxlength=\"40\" autocomplete=\"address-level2\"></div>\n      </div>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fConsent\" required> <span>Ich bin einverstanden, dass meine Daten verarbeitet werden, um mir die Ergebnisse zu senden und mit mir Kontakt aufzunehmen *</span></label>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fNews\"> <span>Ich möchte hilfreiche Materialien über Beziehungen, Anpassung und das Leben in der Emigration erhalten</span></label>\n      <p class=\"err\" id=\"formErr\" hidden></p>\n      <div class=\"row\">\n        <button class=\"btn\" type=\"submit\" id=\"pdfBtn\">PDF erhalten</button>\n        <button class=\"btn ghost\" type=\"button\" id=\"again\">Noch einmal machen</button>\n      </div>\n      <p class=\"note\">Deine Daten sieht nur Iryna Voznesenskaya. Sie werden nicht an Dritte weitergegeben.</p>\n    </form>\n    <span class=\"status\" id=\"status\" hidden></span>\n  </div>`;\n}\ndocument.querySelectorAll('[data-lead]').forEach(el => el.innerHTML = leadFormHtml());\n(function fillCountries(){\n  const sel = document.getElementById('fCountry'); if (!sel) return;\n  const g1 = document.createElement('optgroup'); g1.label = 'Häufig gewählt';\n  COUNTRY_TOP.forEach(c => g1.appendChild(new Option(countryName(c), countryRu(c))));\n  const g2 = document.createElement('optgroup'); g2.label = 'Alle Länder';\n  COUNTRY_ALL.map(c => [countryName(c), countryRu(c)]).sort((x, y) => x[0].localeCompare(y[0], PAGE_LANG)).forEach(([n, v]) => g2.appendChild(new Option(n, v)));\n  g2.appendChild(new Option('Anderes Land', OTHER_COUNTRY));\n  sel.appendChild(g1); sel.appendChild(g2);\n})();\n\nconst el = id => document.getElementById(id);\nfunction setStatus(t){ el('status').textContent = t; el('status').hidden = !t; }\nfunction setErr(t){ el('formErr').textContent = t; el('formErr').hidden = !t; }\nel('again').addEventListener('click', () => { el('result').hidden = true; el('intro').hidden = false; window.scrollTo(0,0); });\n\nconst LS = 'irinaTestsLead';\nfunction loadLead(){ try { return JSON.parse(localStorage.getItem(LS) || 'null'); } catch(e){ return null; } }\nfunction saveLead(v){ try { localStorage.setItem(LS, JSON.stringify(v)); } catch(e){} }\n\nconst _showResult = showResult;\nshowResult = function(){\n  _showResult();\n  const saved = loadLead();\n  el('fName').value = saved?.name || LEAD_HOOKS.personName() || '';\n  if (saved){\n    el('fEmail').value = saved.email || ''; el('fContact').value = saved.contact || '';\n    el('fCountry').value = (COUNTRIES.includes(saved.country) || saved.country === OTHER_COUNTRY) ? saved.country : '';\n    el('fCity').value = saved.city || '';\n  }\n  setErr(''); setStatus('');\n};\n\n// Чёткость PDF: 3 = около 290 точек на дюйм (хорошо для печати). На слабых телефонах — 2.5.\nconst PDF_SCALE = (/iPhone|iPad|Android/i.test(navigator.userAgent) && (navigator.deviceMemory || 4) < 4) ? 2.5 : 3;\nasync function buildPdf(){\n  const stage = el('stage'); stage.innerHTML = '';\n  const blocks = buildBlocks();\n  const pages = [];\n  const newPage = () => {\n    const p = document.createElement('div'); p.className = 'pdf-page';\n    p.innerHTML = `<div class=\"strip\"></div><div class=\"pbody\"></div><div class=\"pfoot\"><span>${footerLine()}</span><span class=\"pn\"></span></div>`;\n    stage.appendChild(p); pages.push(p); return p.querySelector('.pbody');\n  };\n  let body = newPage();\n  for (const b of blocks){\n    if (!b.html) continue;\n    if (b.newPage && body.children.length) body = newPage();\n    const holder = document.createElement('div'); holder.innerHTML = b.html; const node = holder.firstElementChild;\n    body.appendChild(node);\n    if (body.scrollHeight > body.clientHeight + 1 && body.children.length > 1){ node.remove(); body = newPage(); body.appendChild(node); }\n  }\n  pages.forEach((p, i) => p.querySelector('.pn').textContent = `${i+1} / ${pages.length}`);\n  if (document.fonts && document.fonts.ready) await document.fonts.ready;\n  const { jsPDF } = window.jspdf;\n  const pdf = new jsPDF({ unit:'pt', format:'a4', compress:true });\n  const bg = getComputedStyle(document.documentElement).getPropertyValue('--pdf-bg').trim() || '#FFFFFF';\n  for (let i = 0; i < pages.length; i++){\n    const canvas = await html2canvas(pages[i], { scale:PDF_SCALE, backgroundColor:'#FFFFFF', useCORS:true, logging:false });\n    if (i) pdf.addPage();\n    pdf.addImage(canvas.toDataURL('image/jpeg', 0.95), 'JPEG', 0, 0, 595.28, 841.89, undefined, 'FAST');\n    const pr = pages[i].getBoundingClientRect(), k = 595.28 / pr.width;\n    pages[i].querySelectorAll('a[href]').forEach(a => {\n      if (!/^https?:/.test(a.href)) return;\n      const r = a.getBoundingClientRect();\n      pdf.link((r.left - pr.left) * k, (r.top - pr.top) * k, r.width * k, r.height * k, { url: a.href });\n    });\n  }\n  stage.innerHTML = '';\n  return pdf.output('blob');\n}\n\nfunction translit(t){\n  const m = {а:'a',б:'b',в:'v',г:'g',д:'d',е:'e',ё:'e',ж:'zh',з:'z',и:'i',й:'y',к:'k',л:'l',м:'m',н:'n',о:'o',п:'p',р:'r',с:'s',т:'t',у:'u',ф:'f',х:'kh',ц:'ts',ч:'ch',ш:'sh',щ:'sch',ъ:'',ы:'y',ь:'',э:'e',ю:'yu',я:'ya',і:'i',ї:'yi',є:'ye',ґ:'g'};\n  return String(t).toLowerCase().split('').map(c => m[c] ?? c).join('').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');\n}\nlet downloadsCap = null;\n(async () => { try { if (window.claude && window.claude.use) downloadsCap = await window.claude.use('downloads'); } catch(e){ downloadsCap = null; } })();\nasync function saveBlob(blob, filename){\n  if (downloadsCap){ await downloadsCap.save({ filename, data: blob }); return; }\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href = url; a.download = filename; a.rel = 'noopener'; document.body.appendChild(a); a.click(); setTimeout(() => a.remove(), 1000);\n  setTimeout(() => URL.revokeObjectURL(url), 60000);\n}\n\nasync function sendLead(lead){\n  if (!ENDPOINT) return;\n  const src = new URLSearchParams(location.search);\n  const sv = surveyAnswers();\n  const t = LEAD_HOOKS.payload();\n  const payload = {\n    ...lead,\n    testId: TEST_META.id, testName: TEST_META.name, lang: PAGE_LANG,\n    heard: sv.heard.join(', '), interest: sv.interest.join(', '),\n    result: t.result, scores: t.scores, notes: t.notes || '',\n    source: src.get('utm_source') || src.get('src') || document.referrer || 'прямой заход'\n  };\n  try {\n    await fetch(ENDPOINT, { method:'POST', mode:'no-cors', headers:{ 'Content-Type':'text/plain;charset=utf-8' }, body: JSON.stringify(payload) });\n  } catch(e){ /* PDF всё равно выдаётся */ }\n}\n\nel('lead').addEventListener('submit', async (ev) => {\n  ev.preventDefault(); setErr('');\n  const lead = {\n    name: el('fName').value.trim(), email: el('fEmail').value.trim(), contact: el('fContact').value.trim(),\n    country: el('fCountry').value.trim(), city: el('fCity').value.trim(), marketing: el('fNews').checked\n  };\n  if (!lead.name) return setErr('Schreib bitte deinen Namen.');\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(lead.email)) return setErr('Prüf bitte deine E-Mail-Adresse: Sie scheint einen Fehler zu enthalten.');\n  if (!lead.country) return setErr('Wähle bitte ein Land aus der Liste.');\n  if (!el('fConsent').checked) return setErr('Um das PDF zu erhalten, brauche ich dein Einverständnis zur Datenverarbeitung.');\n  if (!window.jspdf || !window.html2canvas) return setErr('Das PDF-Modul konnte nicht geladen werden. Prüf deine Internetverbindung und lade die Seite neu.');\n  const btn = el('pdfBtn'); btn.disabled = true; setStatus('PDF wird vorbereitet…');\n  try {\n    saveLead(lead);\n    window.__leadCountry = lead.country;\n    await sendLead(lead);\n    const blob = await buildPdf();\n    await saveBlob(blob, [LEAD_HOOKS.fileBase(), ...LEAD_HOOKS.fileNames().map(translit)].filter(Boolean).join('_') + '.pdf');\n    setStatus('Fertig! Das PDF ist gespeichert. Wenn es sich nicht geöffnet hat, schau im Ordner «Downloads» nach.');\n  } catch(e){\n    setStatus('');\n    setErr(e && e.code === 'declined' ? 'Speichern abgebrochen.' : 'Das PDF konnte nicht erstellt werden. Versuch es bitte noch einmal.');\n  } finally { btn.disabled = false; }\n});\nwindow.__buildPdf = buildPdf;\n"]};
